import {GestureRecorder} from './automation.mjs';
import {MidiClock} from './midi-clock.mjs';
import {EFFECTS,CATEGORIES,formatEffectValue} from './effects.mjs';
import {createState,clamp,getPath,setPath,makeEffect,formatValue,TIME_CONTROLS,TIME_SELECTS,TIME_TOGGLES,TONAL_SCALES,TONAL_CHORDS,MAIN_CONTROLS,SHAPES,RATES,GRAPH_RATES,SEQ_RATES,FACTORIES,factoryPreset,sanitizeState,getParameterOptions} from './state.mjs';
import {lfoShape,prepareGraph,graphValue,mapTarget} from './modulation.mjs';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readStore=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const writeStore=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Lokaler Speicher ist voll oder gesperrt.',true);return false;}};
let state=createState(),page='time',seqEngine='stutter',seqPattern=0,dirty=false,toastTimer,sendTimer,saveTimer,meters={beat:0,step:0,mods:[0,0,0,0],graphs:[0,0,0]},waveData=null,sourceInfo={},recordSeconds=0;
let userPresets=readStore('dd-presets-v1',[]).filter(p=>p&&typeof p.name==='string'&&p.state).slice(0,64),settings=readStore('dd-settings-v1',{theme:'olive',accent:null,scale:1});
try{const saved=readStore('dd-session-v1',null);if(saved)state=sanitizeState(saved);}catch{}
const host=new AudioHost(),midi=new MidiClock(),motion=new GestureRecorder(),fxChannels=new Map(),sliceSelection=new Map(),graphHandles=new Set();
let motionReplayAcknowledged=false,motionReplayRequestedAt=0;
settings.clock='internal';state.clock.source='internal'; // MIDI input and browser permission are explicitly selected in each session.
const themes={olive:['OLIVE','#c6d66d'],graphite:['GRAPHITE','#b2d6cb'],oxide:['OXIDE','#e8af6d'],paper:['PAPER','#48613b']};
function applyTheme(name,accent=null){if(!themes[name])name='olive';settings.theme=name;settings.accent=accent;document.documentElement.dataset.theme=name;document.documentElement.style.removeProperty('--accent');document.documentElement.style.removeProperty('--accent-rgb');if(accent&&/^#[0-9a-f]{6}$/i.test(accent)){document.documentElement.style.setProperty('--accent',accent);document.documentElement.style.setProperty('--accent-rgb',[1,3,5].map(i=>parseInt(accent.slice(i,i+2),16)).join(','));}writeStore('dd-settings-v1',settings);}
applyTheme(settings.theme,settings.accent);document.documentElement.style.zoom=clamp(settings.scale??1,.8,1.3);
function toast(message,error=false){clearTimeout(toastTimer);const n=$('#toast');n.textContent=message;n.className=error?'show error':'show';toastTimer=setTimeout(()=>n.className='',error?7000:3500);}
function sources(){return [...state.mods.map((s,i)=>({label:`MOD ${i+1}`,key:`mods.${i}`,targets:s.targets,max:6})),...state.graphs.map((s,i)=>({label:`GRAPH ${i+1}`,key:`graphs.${i}`,targets:s.targets,max:6})),...state.macros.map((s,i)=>({label:`MACRO ${i+1}`,key:`macros.${i}`,targets:s.targets,max:5})),{label:'X AXIS',key:'xy.targetsX',targets:state.xy.targetsX,max:5},{label:'Y AXIS',key:'xy.targetsY',targets:state.xy.targetsY,max:5}];}
function sourceByKey(key){return sources().find(s=>s.key===key);}
function canonicalPath(path){const p=String(path).split('.');if(p[0]==='fx'&&p.length===3&&p[2]!=='mix'&&p[2]!=='gain'&&typeof state.fx.find(f=>f.id===p[1])?.params?.[p[2]]==='number')p.splice(2,0,'params');return p.join('.');}
function assignedSource(path){const active=meters.sources?.[path]??Object.entries(meters.sources||{}).find(([p])=>canonicalPath(p)===canonicalPath(path))?.[1];if(active==='automation')return {label:'MOTION',key:'automation',targets:[]};if(active){const key=active[0]==='m'?`mods.${active[1]}`:active[0]==='g'?`graphs.${active[1]}`:active[0]==='c'?`macros.${active[1]}`:active==='x'?'xy.targetsX':active==='y'?'xy.targetsY':null;if(key){const source=sourceByKey(key);if(source)return source;}}return sources().find(s=>s.targets.some(t=>canonicalPath(t.path)===canonicalPath(path)));}

function assignment(path){const source=assignedSource(path);if(!source)return '';if(source.key.startsWith('mods.')){const i=+source.key.split('.')[1],live=meters.values?.[`mods.${i}.type`],options=getParameterOptions(`mods.${i}.type`,state),type=Number.isFinite(live)?options[Math.round(live*(options.length-1))]:state.mods[i].type;return `${{lfo:'LFO',rand:'RAN',env:'ENV'}[type]}${i+1}`;}return source.label.replace('MACRO ','M').replace('GRAPH ','G').replace(' AXIS','');}
function motionValue(path,value){const options=getParameterOptions(path,state);if(options&&typeof value==='string')return {value:Math.max(0,options.indexOf(value))/Math.max(1,options.length-1),kind:'enum'};if(path==='tonal.root')return {value:clamp(value/11),kind:'integer'};return {value,kind:typeof value==='boolean'?'boolean':undefined};}
function captureGesture(path,value){const v=motionValue(path,value);if(typeof v.value!=='number'&&typeof v.value!=='boolean')return;host.gesture(path,v.value);if(motion.active){const active=motion.active;motion.capture(path,v.value,host.context?.currentTime??performance.now()/1000,v.kind);if(active&&!motion.active)queueMicrotask(()=>{stopMotion();toast('Aufnahmelimit erreicht · Bewegung gespeichert.');});}}

function markDirty(){dirty=true;$('#preset-select')?.setAttribute('title',`${state.presetName} · geändert`);const opt=$('#preset-select')?.selectedOptions?.[0];if(opt)opt.textContent=state.presetName+' •';clearTimeout(saveTimer);saveTimer=setTimeout(()=>writeStore('dd-session-v1',state),400);}
function send(){clearTimeout(sendTimer);sendTimer=setTimeout(()=>host.send(state),20);}
function changed(path,value,{final=false}={}){if(!setPath(state,path,value))return;captureGesture(path,value);if(path.startsWith('fx.')){const ps=path.split('.'),f=state.fx.find(f=>f.id===ps[1]);if(f?.lrLock&&ps[2]==='params'&&f.paramsR)f.paramsR[ps[3]]=value;if(f&&ps[2]==='lrLock'&&value){f.paramsR={...f.params};fxChannels.delete(f.id);}}markDirty();send();if(path.startsWith('time.')){const key=path.split('.')[1];if(!['on','stop'].includes(path.split('.')[2])&&!state.time[key].on){state.time[key].on=true;captureGesture(`time.${key}.on`,true);const engine=$(`[data-engine="${key}"]`);engine?.classList.remove('off');const b=$(`[data-toggle="time.${key}.on"]`);b?.classList.add('active');b?.setAttribute('aria-pressed','true');}if(final&&path==='time.vari.scratch'){state.time.vari.scratch=.5;captureGesture(path,.5);knobUpdate(path,.5);send();}}
 if(path.startsWith('xy.'))updateXY();
 if(path.startsWith('mapping.'))drawMapping();
}
function knobUpdate(path,value){$$('d-knob').filter(n=>n.dataset.path===path).forEach(n=>n.setValue(value));}

class DeviceKnob extends HTMLElement{
 connectedCallback(){if(this.ready)return;this.ready=true;this.value=clamp(this.getAttribute('value'));this.defaultValue=clamp(this.getAttribute('default')??.5);this.format=this.getAttribute('format')||'percent';this.options=this.getAttribute('options')?JSON.parse(this.getAttribute('options')):null;this.tabIndex=0;this.setAttribute('role','slider');this.setAttribute('aria-valuemin','0');this.setAttribute('aria-valuemax','100');this.setAttribute('aria-label',this.getAttribute('label'));this.innerHTML=`<span class="knob-graphic"><svg viewBox="0 0 64 64" aria-hidden="true"><path class="track" d="M 12.2 51.8 A 28 28 0 1 1 51.8 51.8"/><path class="progress" d="M 12.2 51.8 A 28 28 0 1 1 51.8 51.8" pathLength="100"/><circle class="face" cx="32" cy="32" r="21"/><circle class="face-inner" cx="32" cy="32" r="17.5"/><line class="needle" x1="32" y1="17" x2="32" y2="25"/></svg></span><span class="knob-name">${esc(this.getAttribute('label'))}</span><span class="knob-value"></span><span class="mod-badge"></span>`;this.setValue(this.value);this.badge();
  this.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('.mod-badge'))return;e.preventDefault();if(this.classList.contains('controller-locked')){openAssignForTarget(this.dataset.path);return;}this.focus();this.drag={y:e.clientY,value:this.value,moved:false};this.setPointerCapture(e.pointerId);this.classList.add('dragging');});
  this.addEventListener('pointermove',e=>{if(!this.drag)return;this.drag.moved=true;this.edit(this.drag.value+(this.drag.y-e.clientY)/(e.shiftKey?1800:180));});
  const end=e=>{if(!this.drag)return;this.drag=null;this.classList.remove('dragging');this.dispatchEvent(new CustomEvent('paramchange',{bubbles:true,detail:{path:this.dataset.path,value:this.value,final:true}}));};this.addEventListener('pointerup',end);this.addEventListener('pointercancel',end);
  this.addEventListener('dblclick',e=>{e.preventDefault();this.edit(this.defaultValue);});
  this.addEventListener('wheel',e=>{e.preventDefault();this.edit(this.value+(e.deltaY<0?1:-1)*(e.shiftKey?.001:.01));},{passive:false});
  this.addEventListener('keydown',e=>{const d={ArrowUp:1,ArrowRight:1,ArrowDown:-1,ArrowLeft:-1}[e.key];if(d){e.preventDefault();e.stopPropagation();this.edit(this.value+d*(e.shiftKey?.001:.01));}if(e.key==='Home'){e.preventDefault();this.edit(0);}if(e.key==='End'){e.preventDefault();this.edit(1);}});
  this.addEventListener('contextmenu',e=>{e.preventDefault();openAssignForTarget(this.dataset.path);});this.addEventListener('mouseenter',()=>{const hint=$('#hint');if(hint)hint.textContent=`${targetLabel(this.dataset.path)} · ${this.display()} · Rechtsklick zum Zuweisen`;});
 }
 display(){const parts=this.dataset.path?.split('.')||[];if(parts[0]==='fx'&&['params','paramsR'].includes(parts[2])){const f=state.fx.find(f=>f.id===parts[1]);if(f)return formatEffectValue(f.type,parts[3],this.value,{...state.tonal,snap:f.snap,params:f[parts[2]],bpm:state.bpm,sampleRate:host.context?.sampleRate??48000,sync:f.sync});}const k=parts[1];const t=parts[0]==='main'?state.main:state.time[k]||state.time.stutter;return formatValue(this.value,this.format,this.options,{...t,engine:k,bpm:state.bpm,sampleRate:host.context?.sampleRate??48000});}
 setValue(v,displayOnly=false){const saved=this.value;this.value=clamp(v);if(!this.ready)return;this.querySelector('.progress').style.strokeDasharray=`${this.value*100} 100`;this.querySelector('.needle').setAttribute('transform',`rotate(${-135+this.value*270} 32 32)`);this.querySelector('.knob-value').textContent=this.display();this.setAttribute('aria-valuenow',Math.round(this.value*100));this.setAttribute('aria-valuetext',this.display());if(displayOnly)this.value=saved;}
 edit(v){if(this.getAttribute('aria-disabled')==='true'||this.classList.contains('controller-locked'))return;this.setValue(v);this.dispatchEvent(new CustomEvent('paramchange',{bubbles:true,detail:{path:this.dataset.path,value:this.value}}));}
 badge(){const a=assignment(this.dataset.path),source=assignedSource(this.dataset.path);this.classList.toggle('modulated',!!a);this.classList.toggle('controller-locked',sources().some(s=>(s.key.startsWith('macros.')||s.key.startsWith('xy.'))&&s.targets.some(t=>canonicalPath(t.path)===canonicalPath(this.dataset.path))));const badge=this.querySelector('.mod-badge');if(badge){badge.textContent=a||'';badge.setAttribute('role','button');badge.tabIndex=a?0:-1;badge.title='Zur steuernden Quelle wechseln · Rechtsklick auf Regler zum Bearbeiten';badge.onclick=e=>{e.stopPropagation();if(!source)return;setPage(source.key==='automation'||source.key.startsWith('macros.')||source.key.startsWith('xy.')?'perform':'animate');const owner=$(`[data-add-target="${source.key}"], [data-edit-target="${source.key}"]`);owner?.closest('section')?.scrollIntoView({block:'center',behavior:'smooth'});};badge.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();badge.click();}};}}

}
customElements.define('d-knob',DeviceKnob);
function knob(path,label,def=.5,format='percent',cls='',options){const v=getPath(state,path)??def;return `<d-knob class="${cls}" data-path="${esc(path)}" label="${esc(label)}" value="${v}" default="${def}" format="${format}"${options?` options="${esc(JSON.stringify(options))}"`:''}></d-knob>`;}
const toggle=(path,label,cls='small')=>`<button class="${cls} ${getPath(state,path)?'active':''}" data-toggle="${path}" aria-pressed="${!!getPath(state,path)}">${label}</button>`;
const segmented=(path,options)=>`<div class="segmented">${options.map(([v,l])=>`<button data-value-path="${path}" data-value="${esc(JSON.stringify(v))}" class="${getPath(state,path)===v?'active':''}" aria-pressed="${getPath(state,path)===v}">${l}</button>`).join('')}</div>`;
const select=(path,options,value=getPath(state,path),cls='')=>`<select class="${cls}" aria-label="${esc(path)}" data-select="${path}">${options.map(([v,l])=>`<option value="${esc(JSON.stringify(v))}"${v===value?' selected':''}>${esc(l)}</option>`).join('')}</select>`;

function shell(){const factoryGroups=[['INIT',['Init']],['FACTORY / TAPE',['Worn cassette']],['FACTORY / RHYTHM',['Fractured rhythm','Circuit ritual']],['FACTORY / SPACE',['Suspended matter','Glass transmission']]];const opts=factoryGroups.map(([group,names])=>`<optgroup label="${group}">${names.map(n=>`<option value="f:${esc(n)}"${state.presetName===n?' selected':''}>${esc(n)}</option>`).join('')}</optgroup>`);if(userPresets.length)opts.push(`<optgroup label="USER">${userPresets.map((p,i)=>`<option value="u:${i}"${state.presetName===p.name?' selected':''}>${esc(p.name)}</option>`).join('')}</optgroup>`);if(!FACTORIES.includes(state.presetName)&&!userPresets.some(p=>p.name===state.presetName))opts.push(`<option selected value="current">${esc(state.presetName)}</option>`);

 $('#app').innerHTML=`<main class="instrument"><header class="masthead"><div class="brand"><svg class="brand-wave" viewBox="0 0 36 28" aria-hidden="true"><path d="M2 19V11M6 24V7M10 17V10M14 26V2M18 22V5M22 18V9M26 24V6M30 18V10M34 16V12" fill="none" stroke="currentColor" stroke-width="2"/></svg><div><h1>DA DESTRUCTOR</h1><small>TIME / TEXTURE / MUTATION</small></div></div><div class="preset-control"><button data-action="prev-preset" title="Vorheriges Preset">‹</button><select id="preset-select" aria-label="Preset">${opts.join('')}</select><button data-action="save-preset" title="Preset speichern">≡</button><button data-action="next-preset" title="Nächstes Preset">›</button></div><button class="primary audio-button" data-action="audio">● &nbsp; START AUDIO</button><button class="source-button" data-page="source"><small>SRC</small> ${esc(host.sourceKind==='live'?'Audio input':host.sourceKind==='file'?'Audio file':'Factory loop')}<span>›</span></button><button class="icon pause-button" data-action="transport" title="Wiedergabe / Pause" aria-label="Wiedergabe / Pause">Ⅱ</button><span class="muted" aria-hidden="true">◖</span><input class="monitor-slider" type="range" min="0" max="1" step=".01" value="${host.monitor}" aria-label="Monitor-Lautstärke" id="monitor-volume"><button class="bypass" data-toggle="bypass" aria-pressed="${state.bypass}"><i class="led"></i>BYPASS</button><button class="danger panic" data-action="panic" title="Escape · Stopp und Audiospeicher leeren">△ &nbsp; PANIC</button><button class="icon help-button" data-action="help" title="Bedienhilfe" aria-label="Bedienhilfe">?</button></header><div class="workspace"><div class="work-main"><nav class="tabs" aria-label="Instrument-Seiten">${[['time','TIME'],['fx','FX RACK'],['animate','ANIMATE'],['perform','PERFORM'],['source','PLAY / LOAD'],['config','CONFIG']].map(([id,name])=>`<button data-page="${id}" class="${page===id?'active':''}" aria-current="${page===id?'page':'false'}"><i class="led ${id==='time'&&Object.values(state.time).some(t=>t.on)||id==='fx'&&state.fx.length?'lit':''}"></i>${name}</button>`).join('')}</nav><section class="source-strip" aria-label="Audio und Transport"><div class="source-meta"><span class="label" id="source-label">${host.sourceKind==='live'?'LIVE INPUT':'LOOP SOURCE'}</span><strong id="source-name">${esc(host.sourceName)}</strong><small id="source-description">${sourceDescription()}</small></div><div class="wave-wrap"><span class="wave-label">STEREO BUFFER / <span id="time-display">00:00.00</span></span><canvas id="waveform" aria-label="Quell-Wellenform"></canvas><i class="wave-playhead" id="playhead"></i></div><div class="clock-block"><label>INTERNAL CLOCK</label><div><input id="bpm" type="number" min="30" max="300" step=".1" value="${state.bpm}" aria-label="Tempo in BPM"><span class="mono muted"> BPM</span></div><div class="beat-dots">${Array.from({length:4},()=>'<i></i>').join('')}</div></div></section><div id="page" class="page"></div></div><aside class="master" aria-label="Master-Sektion"><span class="master-heading">MAIN</span><div class="meter-pair"><div class="meter-track"><b id="meter-l"></b></div><div class="meter-track"><b id="meter-r"></b></div></div><span class="peak-label" id="peak-readout">−∞ dB</span><div class="separator"></div>${MAIN_CONTROLS.slice(0,1).map(([k,l,d,f])=>knob(`main.${k}`,l,d,f)).join('')}<div class="separator"></div>${MAIN_CONTROLS.slice(1,4).map(([k,l,d,f])=>knob(`main.${k}`,l,d,f)).join('')}<div class="separator"></div>${MAIN_CONTROLS.slice(4).filter(([k])=>k!=='autoGain').map(([k,l,d,f])=>knob(`main.${k}`,l,d,f)).join('')}<div class="master-bottom"><button class="rec ${host.recording?'active':''}" data-action="record">● &nbsp; ${host.recording?'STOP REC':'REC WAV'}</button></div></aside></div><footer class="footer"><span id="hint" class="hint">Bereit · Demo-Loop laden oder eigene Audiodatei hineinziehen.</span><span class="footer-keys"><kbd>Shift</kbd> fein &nbsp; <kbd>Doppelklick</kbd> reset &nbsp; <kbd>Rechtsklick</kbd> modulation &nbsp; <kbd>Esc</kbd> panic</span><span>DA / 2.0</span></footer></main>`;
 renderPage();updateTransport();drawWaveform();}
function sourceDescription(){return host.sourceKind==='live'?'STEREO / LIVE':`${(sourceInfo.duration||host.buffer?.duration||8).toFixed(2)} s · ${sourceInfo.sampleRate?Math.round(sourceInfo.sampleRate/1000)+' kHz':'120 BPM'} · STEREO`;}
function tonalControls(){return `<h3 style="margin-top:25px">TONAL GRID / SNAP</h3><div class="settings-row"><label>ROOT</label>${select('tonal.root',['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B'].map((n,i)=>[i,n]))}<label style="min-width:0">SCALE</label>${select('tonal.scale',TONAL_SCALES.map(n=>[n,n.toUpperCase()]))}</div><div class="settings-row"><label>CHORD</label>${select('tonal.chord',TONAL_CHORDS.map(n=>[n,n.toUpperCase()]))}</div><p>SNAP im FX RACK bindet gestimmte Parameter an diese Tonart.</p>`;}
function clockControls(){return `<h3 style="margin-top:25px">CLOCK / MIDI</h3><div class="settings-row"><label>SOURCE</label><div class="segmented"><button class="${settings.clock!=='midi'?'active':''}" data-action="clock-internal">INTERNAL</button><button class="${settings.clock==='midi'?'active':''}" data-action="clock-midi">MIDI</button></div><button class="small" data-action="enable-midi">${midi.enabled?'REFRESH MIDI':'ENABLE MIDI'}</button></div><div class="settings-row"><label>MIDI INPUT</label><select id="midi-input" aria-label="MIDI Clock Eingang"><option value="">Select input…</option>${midi.inputs.map(p=>`<option value="${esc(p.id)}"${p.id===midi.selectedId?' selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="settings-row"><label>STATUS</label><span class="readout" id="midi-status">${midi.selectedId?'WAITING FOR CLOCK':midi.supported?'NO MIDI INPUT SELECTED':'WEB MIDI UNAVAILABLE'}</span></div><p>MIDI-Clock folgt Tempo und START / CONTINUE / STOP des gewählten Eingangs. Interne Clock steht jederzeit zur Verfügung.</p>`;}
function renderPage(){const root=$('#page');root.innerHTML=({time:timePage,fx:fxPage,animate:animatePage,perform:performPage,source:sourcePage,config:configPage}[page])();if(page==='fx')for(const f of state.fx){if(EFFECTS.find(e=>e.id===f.type)?.snap)$(`[data-fx-id="${f.id}"] .panel-heading .spacer`)?.insertAdjacentHTML('beforebegin',toggle(`fx.${f.id}.snap`,'SNAP'));}if(page==='source')$('.settings-grid',root).insertAdjacentHTML('beforeend',sidechainControls());if(page==='perform')root.insertAdjacentHTML('beforeend',motionControls());if(page==='config'){$('.settings-section',root).insertAdjacentHTML('beforeend',tonalControls());$$('.settings-section',root)[1].insertAdjacentHTML('beforeend',clockControls()+latencyControls());}if(page==='animate')state.graphs.forEach((g,i)=>$(`[data-graph="${i}"]`)?.closest('section')?.querySelector('.panel-heading .spacer')?.insertAdjacentHTML('beforebegin',`<button class="small ${graphHandles.has(i)?'active':''}" data-graph-handles="${i}">HANDLES</button>`));if(page==='fx')state.fx.forEach(f=>{const def=EFFECTS.find(d=>d.id===f.type);if(def?.sliceControls)$(`[data-fx-id="${f.id}"]`)?.insertAdjacentHTML('beforeend',sliceControls(f,def));});$$('d-knob',root).forEach(n=>n.badge());const linked=state.time.stretch.linked&&page==='time'?$('[data-path="time.stretch.pitch"]'):null;if(linked){linked.style.opacity='.3';linked.setAttribute('aria-disabled','true');linked.title='Pitch folgt SPEED im LINK-Modus.';}const capture=state.time.stutter.link&&page==='time'?$('[data-path="time.stutter.capture"]'):null;if(capture){capture.style.opacity='.3';capture.setAttribute('aria-disabled','true');capture.title='CAPTURE folgt dem LINK-Paar des RATE-Reglers.';}const bpmInput=$('#bpm');if(bpmInput)bpmInput.disabled=settings.clock==='midi';const clockTitle=$('.clock-block label');if(clockTitle)clockTitle.textContent=settings.clock==='midi'?'MIDI CLOCK':'INTERNAL CLOCK';requestAnimationFrame(()=>{drawPageCanvases();});}
function setPage(id){if(!['time','fx','animate','perform','source','config'].includes(id))return;page=id;$$('.tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.page===id);b.setAttribute('aria-current',b.dataset.page===id?'page':'false');});renderPage();}

function timePage(){return `<div class="signal-route"><span class="route-label">EFFECT ORDER</span>${select('time.order',[['stretch-vari-stutter','STRETCH › VARI › STUTTER'],['vari-stretch-stutter','VARI › STRETCH › STUTTER'],['stutter-stretch-vari','STUTTER › STRETCH › VARI'],['parallel','PARALLEL']])}<span class="route-line">INPUT → TIME → FX → MAIN → OUT</span><button class="small" data-action="random-time" title="Time-Engines innerhalb der freigegebenen Bereiche würfeln">⚄ TIME</button><button class="small" data-action="random-setup" title="Random Setup">⚙</button></div><div class="engine-grid">${engine('stretch','01','STRETCH','DUAL-GRAIN / CAPTURE & HOLD')}${engine('vari','02','VARISPEED','TAPE MACHINE / PITCH × TIME')}${engine('stutter','03',state.time.stutter.bend?'BENDIT':'STUTTER',state.time.stutter.bend?'BUFFER MUTATION / CIRCUIT MEMORY':'CAPTURE / REPEAT / REARRANGE')}</div>${sequencePanel()}<div class="mini-chain panel"><strong>FX CHAIN</strong><div class="chain-chips">${state.fx.length?state.fx.map((f,i)=>`${i?'<span class="arrow">›</span>':''}<button data-page="fx" class="${f.on?'active':''}">${esc(f.type)}</button>`).join(''):'<span class="empty-chain">Leerer Signalweg · Effekt links im FX RACK hinzufügen.</span>'}</div><button class="small" data-page="fx">OPEN RACK ›</button></div>`;}
function engine(key,index,title,subtitle){const t=state.time[key],bend=key==='stutter'&&t.bend,controls=TIME_CONTROLS[bend?'bend':key].slice(0,6);let tags='',footer='';
 if(key==='stretch'){tags=`${toggle('time.stretch.freeze','FREEZE')}${toggle('time.stretch.reverse','REVERSE')}${toggle('time.stretch.linked','LINK SPEED / PITCH')}`;footer=`${segmented('time.stretch.sync',[[true,'SYNC'],[false,'FREE']])}${toggle('seq.stretch.on','SEQ')}`;}
 if(key==='vari'){tags=`<button class="scratch" data-hold="time.vari.stop" title="Gedrückt halten: Tape-Stop">HOLD TO STOP</button>${segmented('time.vari.model',[[0,'HEAT'],[1,'BITCRUSH']])}`;footer=`${segmented('time.vari.mode',[[0,'FWD'],[.5,'FWD / REV'],[1,'REV']])}`;}
 if(key==='stutter'){tags=`${toggle('time.stutter.freeze','FREEZE')}${toggle('time.stutter.reverse','REVERSE')}${toggle('time.stutter.bend','BEND MODE')}`;footer=`${segmented('time.stutter.sync',[[true,'SYNC'],[false,'FREE']])}${toggle('time.stutter.link','LINK')}${toggle('seq.stutter.on','SEQ')}`;}
 return `<section class="engine ${key} ${bend?'bend':''} ${t.on?'':'off'} panel" data-engine="${key}"><div class="panel-heading"><span class="index">${index}</span><button class="power ${t.on?'active':''}" data-toggle="time.${key}.on" aria-label="${title} ein / aus" aria-pressed="${t.on}"><i class="led"></i></button><h2>${title}</h2><span class="spacer"></span><button class="small" data-random-engine="${key}" title="${title} randomisieren">⚄</button><button class="small" data-random-setup-engine="${key}" title="Random Setup">⚙</button><button class="small" data-action="engine-details" data-engine-key="${key}" title="Weitere Einstellungen">···</button></div><div class="engine-info"><span>${subtitle}</span><span>${key==='stretch'?'2 HEADS':key==='vari'?'1 HEAD':'BUFFER'}</span></div><div class="engine-scope"><canvas data-engine-scope="${key}"></canvas><span>${key==='stretch'?'GRAIN OVERLAP':key==='vari'?'TAPE MOTION':bend?'FRACTURE MAP':'REPEAT ENVELOPE'}</span></div><div class="knob-area">${controls.map(([k,l,d,f])=>knob(`time.${key}.${k}`,l,d,f)).join('')}</div><div class="engine-tags">${tags}</div><div class="engine-footer">${footer}<div class="mix-mini"><label>MIX <output data-output="time.${key}.mix">${Math.round(t.mix*100)} %</output></label><input type="range" min="0" max="1" step=".01" value="${t.mix}" data-range="time.${key}.mix" aria-label="${title} Mix"></div></div></section>`;
}
function sequencePanel(){const q=state.seq[seqEngine];seqPattern=Math.min(seqPattern,q.patterns-1);return `<section class="seq-panel panel"><div class="seq-toolbar">${segmentedLocal('seq-engine',[['stutter','STUTTER SEQ'],['stretch','STRETCH SEQ']],seqEngine)}${toggle(`seq.${seqEngine}.on`,'RUN')}<span class="label">RATE</span>${select(`seq.${seqEngine}.rate`,SEQ_RATES.map((l,i)=>[i/4,l]))}<span class="spacer"></span><span class="label">PATTERNS</span>${select(`seq.${seqEngine}.patterns`,[1,2,3,4].map(i=>[i,`${i} × 16`]))}${segmentedLocal('seq-pattern',Array.from({length:q.patterns},(_,i)=>[i,String.fromCharCode(65+i)]),seqPattern)}<button class="small" data-action="seq-random" title="Steps würfeln">⚄</button><button class="small" data-action="seq-fill">FILL</button><button class="small" data-action="seq-toggle" title="Alle Gates im aktuellen Pattern umkehren">INVERT</button><button class="small" data-action="seq-clear">CLEAR</button></div><div class="seq-steps">${q.steps.slice(seqPattern*16,seqPattern*16+16).map((s,i)=>`<div class="seq-step ${s.on?'':'disabled'}" tabindex="0" role="slider" aria-label="${seqEngine} Step ${i+seqPattern*16+1}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(s.value*100)}" data-step="${i+seqPattern*16}"><span class="step-value">${seqEngine==='stretch'?Math.round(s.value*100)+'%':state.time.stutter.bend?formatValue(s.value,'reps'):formatValue(s.value,'division')}</span><i class="step-fill" style="height:${s.value*65+2}px"></i><span class="step-index">${String(i+1).padStart(2,'0')}</span></div>`).join('')}</div><div class="seq-foot"><span>Klick: Gate · Ziehen: Wert · Shift: fein</span><span>${seqEngine==='stretch'?'TARGET / STRETCH SPEED':state.time.stutter.bend?'TARGET / BENDIT REPS':'TARGET / STUTTER RATE'} · <span id="seq-position">${String.fromCharCode(65+seqPattern)} / 16</span></span></div></section>`;}
function segmentedLocal(kind,options,value){return `<div class="segmented">${options.map(([v,l])=>`<button data-local="${kind}" data-local-value="${esc(v)}" class="${v===value?'active':''}">${l}</button>`).join('')}</div>`;}
function fxPage(){return `<div class="fx-layout"><aside class="fx-library panel"><input type="search" id="fx-search" placeholder="FIND EFFECT…" aria-label="Effekte suchen">${CATEGORIES.map(c=>`<details class="fx-category" open><summary>${esc(c)}</summary>${EFFECTS.filter(e=>e.category===c).map(e=>`<button class="effect-option ${state.fx.some(f=>f.type===e.id)?'added':''}" data-add-fx="${esc(e.id)}" draggable="true" title="${esc(e.description)}">${esc(e.name||e.id)}<span class="add-plus">${state.fx.some(f=>f.type===e.id)?'✓':'+'}</span></button>`).join('')}</details>`).join('')}</aside><div class="fx-rack"><div class="fx-rack-header panel"><strong>PROCESSING RACK / ${String(state.fx.length).padStart(2,'0')}</strong><span class="spacer"></span>${segmented('fxMode',[['serial','SERIAL'],['parallel','PARALLEL']])}<button class="small" data-action="random-fx">⚄ FX</button><button class="small" data-action="clear-fx" title="Effekte entfernen">CLEAR</button></div><div class="fx-list" id="fx-list">${state.fx.length?state.fx.map(fxUnit).join(''):`<div class="fx-empty"><span class="empty-symbol">[ + ]</span><p>Ein leerer Signalweg.<br>Wähle einen Effekt aus der Bibliothek und forme deinen Sound.</p><small>62 EFFECTS / DRAG TO REORDER</small><button class="small" data-add-fx="TAPE">+ TAPE</button></div>`}</div></div></div>`;}
function fxUnit(f,i){const d=EFFECTS.find(e=>e.id===f.type);if(!d)return '';const channel=!f.lrLock&&fxChannels.get(f.id)==='R'?'paramsR':'params';const primary=d.params.filter(p=>!p.advanced),advanced=d.params.filter(p=>p.advanced);const control=p=>knob(`fx.${f.id}.${channel}.${p.key}`,p.label,p.default??.5,p.format||'percent','small-knob',p.options);return `<section class="fx-unit panel ${f.on?'':'off'} ${f.muted?'muted-unit':''}" data-fx-id="${f.id}"><div class="panel-heading" draggable="true" data-drag-fx="${f.id}"><span class="index">${String(i+1).padStart(2,'0')}</span><button class="power ${f.on?'active':''}" data-toggle="fx.${f.id}.on" aria-label="${esc(d.name)} ein / aus" aria-pressed="${f.on}"><i class="led"></i></button><h3>${esc(d.name||d.id)}</h3><span class="spacer"></span>${toggle(`fx.${f.id}.muted`,'MUTE')}${toggle(`fx.${f.id}.lrLock`,'L/R LOCK')}${d.canSync?toggle(`fx.${f.id}.sync`,'SYNC'):''}<button class="small" data-random-setup-fx="${f.id}" title="Random Setup">⚙</button><button class="small" data-random-fx="${f.id}" title="Effekt würfeln">⚄</button><button class="small" data-fx-up="${f.id}" aria-label="Effekt nach oben">↑</button><button class="small" data-fx-down="${f.id}" aria-label="Effekt nach unten">↓</button><button class="small" data-remove-fx="${f.id}" aria-label="Effekt entfernen">×</button></div><div class="fx-subheading"><p class="fx-description">${esc(d.description)}</p>${!f.lrLock?`<div class="segmented"><button data-fx-channel="${f.id}" data-channel="L" class="${channel==='params'?'active':''}">LEFT</button><button data-fx-channel="${f.id}" data-channel="R" class="${channel==='paramsR'?'active':''}">RIGHT</button></div>`:''}</div><div class="fx-visualizer"><canvas data-fx-scope="${f.id}" aria-label="${esc(f.type)} Audioausgang"></canvas><span data-fx-level="${f.id}">−∞ dB</span></div><div class="fx-controls">${primary.map(control).join('')}<i class="fx-divider"></i>${knob(`fx.${f.id}.gain`,'GAIN',.5,'fxgain','small-knob')}${knob(`fx.${f.id}.mix`,'MIX',.5,'percent','small-knob')}</div>${advanced.length?`<details class="fx-advanced"><summary>DETAILS / ${advanced.length} CONTROLS</summary><div class="fx-controls">${advanced.map(control).join('')}</div></details>`:''}</section>`;}

function targetLabel(path){const parts=String(path).split('.');if(parts[0]==='fx'){const f=state.fx.find(f=>f.id===parts[1]);if(!f)return 'FX / removed';const d=EFFECTS.find(e=>e.id===f.type);return `${f.type} / ${d?.params.find(p=>p.key===parts.at(-1))?.label||parts.at(-1).toUpperCase()}`;}return path.replace('time.','').replaceAll('.',' / ').toUpperCase();}
function targetSlots(key){const s=sourceByKey(key);return `<div class="targets"><span class="uppercase muted">TARGETS <span class="accent">${s.targets.length}/${s.max}</span></span>${s.targets.map((t,i)=>`<div class="target-row"><button class="target-name" data-edit-target="${key}" data-target-index="${i}" title="Routing-Kurve bearbeiten">${esc(targetLabel(t.path))}</button><span class="target-range">${Math.round(t.min*100)}:${Math.round(t.max*100)}</span><button class="target-remove" data-remove-target="${key}" data-target-index="${i}" aria-label="Zuweisung entfernen">×</button></div>`).join('')}${s.targets.length<s.max?`<button class="target-add" data-add-target="${key}">+ ASSIGN TARGET</button>`:''}</div>`;}
function animatePage(){return `<div class="mod-grid">${state.mods.map((m,i)=>`<section class="mod-panel panel"><div class="panel-heading"><span class="index">${String(i+1).padStart(2,'0')}</span><h2>MODULATOR</h2><span class="mod-status" id="mod-val-${i}">0.00</span></div>${segmented(`mods.${i}.type`,[['lfo','LFO'],['rand','RAND'],['env','ENV']])}<div class="mod-scope"><canvas data-mod-scope="${i}"></canvas></div>${m.type==='lfo'?select(`mods.${i}.shape`,SHAPES.map(s=>[s,s.toUpperCase()]),m.shape,'mod-shape'):m.type==='rand'?`<div class="flex" style="padding:0 10px 8px">${toggle(`mods.${i}.bin`,'BIN / STEPPED')}<span class="muted uppercase">DETERMINISTIC</span></div>`:`<div class="mod-source">${select(`mods.${i}.source`,[['internal','INTERNAL'],['external','EXTERNAL SIDECHAIN']])}</div>`}<div class="mod-controls">${m.type==='env'?`${knob(`mods.${i}.gain`,'GAIN',.5)}${knob(`mods.${i}.rise`,'RISE',.1)}${knob(`mods.${i}.fall`,'FALL',.3)}`:`${knob(`mods.${i}.rate`,'RATE',.4,'modrate')}${knob(`mods.${i}.depth`,'DEPTH',1)}${knob(`mods.${i}.smooth`,'SMOOTH',.1)}`}</div>${m.type==='env'?`<div class="mod-controls">${knob(`mods.${i}.tone`,'TONE',.5,'bipolar')}${knob(`mods.${i}.depth`,'DEPTH',1)}${knob(`mods.${i}.smooth`,'SMOOTH',.1)}</div>`:`<div class="mod-controls">${knob(`mods.${i}.jitter`,'JITTER',0)}</div>`}${targetSlots(`mods.${i}`)}</section>`).join('')}</div><div class="graph-grid">${state.graphs.map((g,i)=>`<section class="graph-panel panel"><div class="panel-heading"><span class="index">G${i+1}</span><h2>CURVE GRAPH</h2><span class="spacer"></span><button class="small" data-graph-settings="${i}" title="Graph-Einstellungen">⚙</button><button class="small" data-reset-graph="${i}" title="Kurve zurücksetzen">↺</button></div><div class="graph-editor" data-graph="${i}" tabindex="0" aria-label="Graph ${i+1}: Klick fügt Punkt hinzu, ziehen verschiebt, Rechtsklick löscht, Shift ziehen formt Kurve"><canvas></canvas></div><div class="graph-toolbar">${select(`graphs.${i}.rate`,(g.timing==='legacy'?RATES:GRAPH_RATES).map((l,j)=>[j/10,l]))}${toggle(`graphs.${i}.reverse`,'REVERSE')}</div>${targetSlots(`graphs.${i}`)}</section>`).join('')}</div><div class="mod-note">GRAPH: Klick fügt einen Punkt hinzu · Ziehen verschiebt ihn · Shift-Ziehen formt das Segment · Rechtsklick entfernt einen Punkt. Rechtsklick auf einen Regler öffnet die Zuweisung.</div>`;}
function performPage(){return `<div class="perform-layout"><div class="macro-grid">${state.macros.map((m,i)=>`<section class="macro panel"><div class="panel-heading"><span class="index">M${i+1}</span><h2>MACRO ${i+1}</h2></div><div class="macro-knob">${knob(`macros.${i}.value`,'AMOUNT',0,'percent','big')}</div><input type="text" maxlength="24" data-macro-name="${i}" value="${esc(m.name)}" aria-label="Macro ${i+1} Name">${targetSlots(`macros.${i}`)}</section>`).join('')}</div><section class="xy-section panel"><div class="panel-heading"><span class="index">XY</span><h2>PERFORMANCE FIELD</h2><span class="spacer"></span><button class="small" data-action="xy-center">CENTER</button></div><div class="xy-pad" id="xy-pad" tabindex="0" role="group" aria-label="XY-Pad. Pfeiltasten bewegen X und Y."><i class="xy-line h" style="top:${(1-state.xy.y)*100}%"></i><i class="xy-line v" style="left:${state.xy.x*100}%"></i><i class="xy-dot" style="left:${state.xy.x*100}%;top:${(1-state.xy.y)*100}%"></i><span class="xy-label y">Y ↑</span><span class="xy-label x">X →</span></div><div class="xy-values"><span id="xy-x">X ${state.xy.x.toFixed(2)}</span><span id="xy-y">Y ${state.xy.y.toFixed(2)}</span></div><div class="xy-targets">${targetSlots('xy.targetsX')}${targetSlots('xy.targetsY')}</div></section></div><div class="performance-note panel">Ein Regler, mehrere Bewegungen. Weise Macros und Achsen bis zu fünf Ziele zu. Über <span class="accent">MIN / MAX / START / END / SKEW</span> formst du den Verlauf jeder Zuweisung. Der Pickup-Modus übernimmt ein Ziel, sobald die Geste dessen aktuellen Wert erreicht.</div>`;}
function sourcePage(){return `<div class="settings-grid"><section class="panel settings-section"><h3>LOOP SOURCE</h3><p>Ziehe eine Audiodatei in das Instrument oder lade sie hier. Die Verarbeitung findet im Browser statt.</p><div class="source-drop"><div class="symbol">↥</div><strong>${esc(host.sourceName)}</strong><p>WAV · MP3 · FLAC · OGG · M4A · Browserabhängig</p><button data-action="load-file">LOAD AUDIO FILE…</button></div><div class="source-details"><div><span>DURATION</span><b>${(host.buffer?.duration||8).toFixed(2)} s</b></div><div><span>SAMPLE RATE</span><b>${host.buffer?Math.round(host.buffer.sampleRate/1000)+' kHz':'—'}</b></div><div><span>CHANNELS</span><b>${host.buffer?.numberOfChannels||2}</b></div></div><div class="settings-row"><button data-action="demo">FACTORY LOOP</button><button class="primary" data-action="transport">${host.playing?'Ⅱ PAUSE':'▶ PLAY'}</button><button data-action="restart">↺ RESTART</button></div><div class="record-strip"><button class="rec ${host.recording?'active':''}" data-action="record">● ${host.recording?'STOP & SAVE':'RECORD WAV'}</button><div><span class="mono" id="record-time">${host.recording?formatTime((performance.now()-host.recordStarted)/1000):'00:00.00'}</span><br><small>Stereo PCM · 16 bit · nach MAIN</small></div></div></section><section class="panel settings-section"><h3>LIVE AUDIO INPUT</h3><p>Verbinde ein Audio-Interface oder nutze einen Browser-Audioeingang. Die Eingangsfreigabe erfolgt beim Verbinden.</p><div class="settings-row"><label>DEVICE</label><select id="input-device" aria-label="Audio-Eingang"><option value="">System default</option></select><button class="icon" data-action="refresh-devices" title="Eingänge aktualisieren">↻</button></div><div class="settings-row"><button data-action="live">CONNECT INPUT</button><button data-action="disconnect">DISCONNECT</button></div><p class="input-note">${host.sourceKind==='live'&&host.playing?`<span class="accent">● ${esc(host.sourceName)}</span>`:'Kein Live-Eingang verbunden.'}</p><p>Für Live-Mikrofone Kopfhörer verwenden. Browser-Echounterdrückung und automatische Pegelkorrektur werden beim Verbinden ausgeschaltet.</p><div class="separator"></div><h3 style="margin-top:25px">SESSION</h3><p>Regler, Routings und Effektkette werden lokal gespeichert. Audiodateien und Live-Aufnahmen werden nicht im Preset gespeichert.</p><div class="settings-row"><button data-action="export-preset">EXPORT PRESET</button><button data-action="import-preset">IMPORT PRESET</button></div><p>Exportiere den Klang mit RECORD WAV. Die Aufnahme enthält den bearbeiteten Ausgang vor der Monitor-Lautstärke.</p></section></div>`;}
function configPage(){return `<div class="settings-grid"><section class="panel settings-section"><h3>DISPLAY / THEME</h3><div class="theme-swatches">${Object.entries(themes).map(([id,[label,color]])=>`<button class="theme-swatch ${settings.theme===id?'active':''}" data-theme-name="${id}" style="--swatch:${color}"><i></i>${label}</button>`).join('')}</div><div class="settings-row"><label>ACCENT</label><input type="color" id="accent-color" value="${settings.accent||themes[settings.theme]?.[1]||'#c6d66d'}" aria-label="Akzentfarbe"><button class="small" data-action="reset-accent">RESET</button></div><div class="settings-row"><label>UI SCALE</label><input type="range" id="ui-scale" min=".8" max="1.3" step=".05" value="${settings.scale||1}" aria-label="UI-Skalierung"><output id="scale-value" class="readout">${Math.round((settings.scale||1)*100)} %</output></div><p>Alle Oberflächen verwenden dieselben Farbvariablen. Rahmen, Vertiefungen, Regler und Statusanzeigen folgen dem gewählten Theme.</p><h3 style="margin-top:25px">PRESETS / STATE</h3><div class="settings-row"><button data-action="save-preset">SAVE USER PRESET</button><button data-action="export-preset">EXPORT JSON</button></div><div class="settings-row"><button data-action="import-preset">IMPORT JSON</button><button data-action="init">RESET TO INIT</button></div>${userPresets.length?`<div class="settings-row"><label>USER PRESET</label><select id="delete-preset">${userPresets.map((p,i)=>`<option value="${i}">${esc(p.name)}</option>`).join('')}</select><button class="small" data-action="delete-preset">REMOVE</button></div>`:''}</section><section class="panel settings-section"><h3>ENGINE / STATUS</h3><div class="settings-row"><label>AUDIO</label><span class="readout">${host.context?host.context.state.toUpperCase():'NOT STARTED'}</span></div><div class="settings-row"><label>SAMPLE RATE</label><span class="readout">${host.context?host.context.sampleRate+' Hz':'DEVICE DEFAULT'}</span></div><div class="settings-row"><label>OUTPUT LATENCY</label><span class="readout">${host.context?Math.round((host.context.baseLatency||0)*1000)+' ms + FX':'—'}</span></div><div class="settings-row"><label>PROCESSING</label><span class="readout">AUDIOWORKLET / STEREO</span></div><div class="settings-row"><label>FX AVAILABLE</label><span class="readout">${EFFECTS.length} / ORIGINAL ALGORITHMS</span></div><p>Eigenständige Umsetzung des Recherche-Briefings. Zeit-, Tape-, Modulations- und Spektralprozesse sind eigene DSP-Algorithmen. Detailmodelle und Klang entsprechen keiner zugesicherten Nachbildung eines Plugins.</p><h3 style="margin-top:25px">CONTROLS</h3>${helpRows()}<div class="settings-row"><button data-action="help">OPEN MANUAL</button><button data-action="panic" class="danger">△ PANIC</button></div></section></div>`;}
function helpRows(){return `<dl class="help-rows"><dt>Drag ↑ ↓</dt><dd>Reglerwert ändern</dd><dt>Shift + Drag</dt><dd>Fein einstellen</dd><dt>Wheel / ↑ ↓</dt><dd>Schrittweise einstellen</dd><dt>Double-click</dt><dd>Standardwert wiederherstellen</dd><dt>Right-click</dt><dd>Modulation oder Macro zuweisen</dd><dt>Space</dt><dd>Wiedergabe / Pause</dd><dt>Esc</dt><dd>Audio stoppen und Speicher leeren</dd><dt>Drop a file</dt><dd>Audiodatei laden</dd></dl>`;}

function motionInitialValues(){const out=Object.fromEntries(allTargets().map(t=>[t.path,getPath(state,t.path)]));for(const engine of ['stretch','vari','stutter'])for(const[k,v]of Object.entries(state.time[engine]))if(typeof v==='boolean'||typeof v==='string')out[`time.${engine}.${k}`]=v;for(const f of state.fx)for(const k of ['on','muted','snap','lrLock','sync'])out[`fx.${f.id}.${k}`]=f[k];state.mods.forEach((m,i)=>{for(const[k,v]of Object.entries(m))if(typeof v==='string')out[`mods.${i}.${k}`]=v;});state.graphs.forEach((g,i)=>{if(g.timing)out[`graphs.${i}.timing`]=g.timing;g.points.forEach((p,j)=>{const handles=graphSegmentHandles(g.points,j);for(let k=0;k<(handles?7:3);k++)out[`graphs.${i}.points.${j}.${k}`]=k<2?p[k]:k===2?p[2]??.5:handles[k-3];});});for(const k of ['stutter','stretch']){out[`seq.${k}.on`]=state.seq[k].on;state.seq[k].steps.forEach((v,i)=>{out[`seq.${k}.steps.${i}.value`]=v.value;out[`seq.${k}.steps.${i}.on`]=v.on;});}out['tonal.root']=state.tonal.root;out['tonal.scale']=state.tonal.scale;out['tonal.chord']=state.tonal.chord;out['time.order']=state.time.order;out.fxMode=state.fxMode;out.bypass=state.bypass;for(const path of Object.keys(out))out[path]=motionValue(path,out[path]).value;return out;}
function captureSequence(){const q=state.seq[seqEngine];for(let i=seqPattern*16;i<seqPattern*16+16;i++){captureGesture(`seq.${seqEngine}.steps.${i}.value`,q.steps[i].value);captureGesture(`seq.${seqEngine}.steps.${i}.on`,q.steps[i].on);}}
function captureGraph(index,point){const points=state.graphs[index].points;for(const j of [...new Set([point,point===0?points.length-1:point===points.length-1?0:point])])for(let k=0;k<points[j].length;k++)captureGesture(`graphs.${index}.points.${j}.${k}`,points[j][k]);}

function motionControls(){const a=state.automation||{duration:0,events:[],loop:true};return `<section class="motion-strip panel"><div class="panel-heading"><span class="index">REC</span><h2>GESTURE AUTOMATION</h2><span class="spacer"></span><span class="mono accent" id="motion-time">${formatTime(motion.active?(host.context?.currentTime??0)-motion.started:a.duration)}</span></div><div class="motion-actions"><button class="rec ${motion.active?'active':''}" data-action="motion-record">● ${motion.active?'STOP MOTION':'REC MOTION'}</button><button class="${state.automationPlaying?'active':''}" aria-pressed="${!!state.automationPlaying}" data-action="motion-play">${state.automationPlaying?'Ⅱ STOP':'▶ PLAY'} MOTION</button>${toggle('automation.loop','LOOP')}<button class="small" data-action="motion-clear">CLEAR</button><span class="muted mono">${a.events.length} EVENTS</span></div><p>Regler-, Macro- und XY-Bewegungen aufnehmen. Wiedergabe und Loop laufen im Audiotakt. Das Preset speichert die Bewegung mit.</p></section>`;}
function stopMotion(){state.automation=motion.stop(host.context?.currentTime??performance.now()/1000);state.automationPlaying=false;markDirty();send();if(page==='perform')renderPage();toast(`Bewegung gespeichert · ${state.automation.events.length} Events`);}
function sidechainControls(){return `<section class="panel settings-section sidechain-section"><h3>EXTERNAL SIDECHAIN</h3><p>Ein unabhängiger Eingang steuert Envelope-Follower und spektrale Anziehung. Er wird nicht auf den hörbaren Ausgang gemischt.</p><div class="settings-row"><label>SOURCE</label><span class="readout" id="sidechain-name">${esc(host.sidechain.name)}</span></div><div class="settings-row"><label>DEVICE</label><select id="sidechain-device" aria-label="Sidechain Audio-Eingang"><option value="">System default</option></select><button class="small" data-action="refresh-devices">↻</button></div><div class="settings-row"><button data-action="sidechain-connect">CONNECT INPUT</button><button data-action="sidechain-file">LOAD SIDECHAIN…</button><button class="small" data-action="sidechain-disconnect">DISCONNECT</button></div><p>Unter ANIMATE bei ENV die Quelle EXTERNAL wählen. Eine geladene Sidechain-Datei loopt gemeinsam mit dem Transport.</p></section>`;}
function latencyControls(){return `<h3 style="margin-top:25px">MASTER / LATENCY</h3><div class="settings-row"><label>COMPENSATE</label>${toggle('latencyComp','LATENCY COMP')}<span id="latency-pending" class="readout">${meters.pendingLatency?'PENDING / STOP TRANSPORT':`${meters.latency||0} SAMPLES`}</span></div><div class="settings-row"><label>GAIN RANGE</label>${select('main.gainMode',[['extended','−∞ … +12 dB'],['legacy','LEGACY / ±24 dB']])}</div><div class="settings-row"><label>AUTO GAIN</label>${knob('main.autoGain','AUTO GAIN',0,'percent','small-knob')}</div><p>Strukturelle Änderungen an spektraler Latenz werden bei laufendem Transport bis zum nächsten Stop vorgemerkt. Auto Gain gleicht die gemessene Pegeländerung gegenüber dem Dry-Signal aus.</p>`;}
function sliceControls(f,d){const index=clamp(sliceSelection.get(f.id)??0,0,31),metadata=d.sliceControls,controls=Array.isArray(metadata)?metadata:[{key:'shuffle',label:'SHUFFLE',default:0},{key:'repeat',label:'REPEAT',default:0},{key:'pitch',label:'PITCH',default:.5,format:'pitch'},{key:'reverse',label:'REVERSE',default:0},{key:'gate',label:'GATE',default:1},{key:'ratchet',label:'RATCHET',default:0}];return `<details class="fx-advanced slice-editor"><summary>PER-SLICE CONTROLS</summary><div class="slice-selector"><label>SLICE</label><select data-slice-selector="${f.id}" aria-label="${f.type} Slice">${Array.from({length:32},(_,i)=>`<option value="${i}"${i===index?' selected':''}>${String(i+1).padStart(2,'0')}</option>`).join('')}</select></div><div class="fx-controls">${controls.map(p=>knob(`fx.${f.id}.slices.${index}.${p.key}`,p.label,p.default??.5,p.format||'percent','small-knob',p.options)).join('')}</div></details>`;}
function reflectMeters(packet){
 const position=$('#motion-time');if(position&&state.automationPlaying&&!motion.active)position.textContent=formatTime(packet.automationPosition||0);
 for(const n of $$('d-knob')){n.badge();const value=packet.values?.[n.dataset.path]??Object.entries(packet.values||{}).find(([p])=>canonicalPath(p)===canonicalPath(n.dataset.path))?.[1];if(Number.isFinite(value)&&!n.drag)n.setValue(value,true);}
 if(state.automationPlaying&&packet.automationPlaying)motionReplayAcknowledged=true;if(state.automationPlaying&&packet.automationPlaying===false&&(motionReplayAcknowledged||!state.automation.loop&&performance.now()-motionReplayRequestedAt>150&&packet.automationPosition>=state.automation.duration)){state.automationPlaying=false;motionReplayAcknowledged=false;host.send(state);const b=$('[data-action="motion-play"]');if(b){b.textContent='▶ PLAY MOTION';b.classList.remove('active');b.setAttribute('aria-pressed','false');}}
 for(const [path,value]of Object.entries(packet.values||{})){if(typeof getPath(state,path)!=='boolean')continue;const active=typeof value==='boolean'?value:value>=.5;for(const button of $$('[data-toggle]').filter(b=>b.dataset.toggle===path)){button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));}const parts=path.split('.');if(parts[0]==='fx'&&parts[2]==='on')$(`[data-fx-id="${parts[1]}"]`)?.classList.toggle('off',!active);if(parts[0]==='time'&&parts[2]==='on')$(`[data-engine="${parts[1]}"]`)?.classList.toggle('off',!active);}
 const status=$('#latency-pending');if(status)status.textContent=packet.pendingLatency?'PENDING / STOP TRANSPORT':`${packet.latency||0} SAMPLES`;
 if(page==='fx')for(const meter of packet.fxMeters||[]){const c=$(`[data-fx-scope="${meter.id}"]`);if(c&&Array.isArray(meter.wave)){const info=canvasContext(c);if(info){const {ctx,w,h,accent}=info;ctx.strokeStyle=accent;ctx.lineWidth=1.1;ctx.beginPath();meter.wave.forEach((v,i)=>{const x=i/Math.max(1,meter.wave.length-1)*w,y=h*.5-clamp(v,-1,1)*h*.45;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}}const label=$(`[data-fx-level="${meter.id}"]`);if(label){const peak=Math.max(meter.peakL||0,meter.peakR||0);label.textContent=peak>1e-5?`${(20*Math.log10(peak)).toFixed(1)} dB`:'−∞ dB';}}
}
function randomEntry(key){const value=randomSettings[key];return typeof value==='number'?{strength:clamp(value,-1,1),probability:1}:{strength:clamp(value?.strength??.5,-1,1),probability:clamp(value?.probability??1)};}
function randomRows(scope='all'){
 const rows=[];
 for(const engine of ['stretch','vari','stutter'])if(scope==='all'||scope===`time:${engine}`){for(const [key,value]of Object.entries(state.time[engine]))if(typeof value==='number')rows.push({key:`${engine}.${key}`,path:`time.${engine}.${key}`,label:`${engine.toUpperCase()} / ${key.toUpperCase()}`});}
 for(const f of state.fx)if(scope==='all'||scope===`fx:${f.id}`){const d=EFFECTS.find(e=>e.id===f.type);for(const channel of f.lrLock?['params']:['params','paramsR'])for(const p of d.params)rows.push({key:`fx.${f.type}.${channel==='paramsR'?'R.':''}${p.key}`,path:`fx.${f.id}.${channel}.${p.key}`,label:`${f.type}${channel==='paramsR'?' R':''} / ${p.label}`});for(const key of ['mix','gain'])rows.push({key:`fx.${f.type}.${key}`,path:`fx.${f.id}.${key}`,label:`${f.type} / ${key.toUpperCase()}`});if(f.slices)for(let i=0;i<f.slices.length;i++)for(const key of Object.keys(f.slices[i]))rows.push({key:`fx.${f.type}.slice${i}.${key}`,path:`fx.${f.id}.slices.${i}.${key}`,label:`${f.type} ${i+1} / ${key.toUpperCase()}`});}
 return rows;
}
function randomizeRows(rows){for(const r of rows){const {strength,probability}=randomEntry(r.key),base=getPath(state,r.path);if(strength===0||Math.random()>probability||typeof base!=='number')continue;changed(r.path,clamp(base+(Math.random()-base)*strength));}}
function randomizeEngine(key){randomizeRows(randomRows(`time:${key}`));state.time[key].on=true;}
function randomizeFX(f){if(f)randomizeRows(randomRows(`fx:${f.id}`));}
function randomSetup(scope='all'){const rows=randomRows(scope);showDialog('RANDOM SETUP',`<p>Stärke 0 sperrt einen Parameter. Positive Stärke bewegt ihn in Richtung eines Zufallswerts; negative Stärke spiegelt die Änderung. PROB ist die Wahrscheinlichkeit pro Würfeln.</p><div class="random-column-head"><span>PARAMETER</span><span>STRENGTH</span><span>PROB</span></div>${rows.map(r=>{const v=randomEntry(r.key);return `<div class="random-row"><label>${esc(r.label)}</label><div><input type="range" min="-1" max="1" step=".05" value="${v.strength}" data-random-strength="${r.key}" aria-label="${esc(r.label)} Stärke"><output>${Math.round(v.strength*100)} %</output></div><div><input type="range" min="0" max="1" step=".05" value="${v.probability}" data-random-probability="${r.key}" aria-label="${esc(r.label)} Wahrscheinlichkeit"><output>${Math.round(v.probability*100)} %</output></div></div>`;}).join('')}<div class="dialog-actions"><button data-close-dialog>DONE</button></div>`);}

// Pointer gestures keep their own state, so an audio/control update never rebuilds a control mid-drag.
document.addEventListener('paramchange',e=>{const {path,value,final}=e.detail;if(path.startsWith('mapping.')){if(mappingDraft){mappingDraft[path.split('.')[1]]=value;previewMapping();drawMapping();}return;}changed(path,value,{final});});
let mappingDraft=null,mappingContext=null;
function previewMapping(){if(!mappingContext||mappingContext.index<0)return;mappingContext.source.targets[mappingContext.index]=structuredClone(mappingDraft);host.send(state);}
function showDialog(title,body){const d=$('#assign-dialog');d.innerHTML=`<div class="dialog-header"><h2>${title}</h2><button data-close-dialog aria-label="Schließen">×</button></div><div class="dialog-body">${body}</div>`;d.onclose=()=>renderPage();if(!d.open)d.showModal();return d;}
function allTargets(){const out=[];const numeric=(obj,prefix,group)=>{for(const[k,v]of Object.entries(obj||{}))if(typeof v==='number')out.push({path:`${prefix}.${k}`,label:`${group} / ${k.toUpperCase()}`,group});};for(const k of ['stretch','vari','stutter'])numeric(state.time[k],`time.${k}`,k.toUpperCase());numeric(state.main,'main','MAIN');for(const f of state.fx){const d=EFFECTS.find(e=>e.id===f.type);for(const channel of f.lrLock?['params']:['params','paramsR'])for(const p of d.params)out.push({path:`fx.${f.id}.${channel}.${p.key}`,label:`${f.type}${f.lrLock?'':channel==='params'?' L':' R'} / ${p.label}`,group:f.type});if(f.slices)for(let i=0;i<f.slices.length;i++)for(const k of Object.keys(f.slices[i]))out.push({path:`fx.${f.id}.slices.${i}.${k}`,label:`${f.type} SLICE ${i+1} / ${k.toUpperCase()}`,group:f.type});for(const k of ['mix','gain'])out.push({path:`fx.${f.id}.${k}`,label:`${f.type} / ${k.toUpperCase()}`,group:f.type});}state.mods.forEach((m,i)=>numeric(m,`mods.${i}`,`MOD ${i+1}`));state.graphs.forEach((g,i)=>numeric(g,`graphs.${i}`,`GRAPH ${i+1}`));state.macros.forEach((m,i)=>numeric(m,`macros.${i}`,`MACRO ${i+1}`));for(const k of ['x','y'])out.push({path:`xy.${k}`,label:`PERFORM / ${k.toUpperCase()}`,group:'PERFORM'});return out;}

function targetOptions(path){const ts=allTargets(),groups=[...new Set(ts.map(t=>t.group))];return groups.map(g=>`<optgroup label="${esc(g)}">${ts.filter(t=>t.group===g).map(t=>`<option value="${esc(t.path)}"${t.path===path?' selected':''}>${esc(t.label)}</option>`).join('')}</optgroup>`).join('');}
function openMapping(key,index=-1,path=''){const src=sourceByKey(key);if(!src)return;if(index<0&&src.targets.length>=src.max){toast('Alle Ziel-Slots sind belegt.');return;}mappingContext={source:src,index,original:index>=0?structuredClone(src.targets[index]):null,committed:false};mappingDraft=structuredClone(src.targets[index]||{path:path||allTargets()[0].path,min:0,max:1,start:0,end:1,skew:.5});const d=showDialog(`${src.label} / TARGET ROUTING`,`<label for="mapping-target">TARGET</label><select id="mapping-target">${targetOptions(mappingDraft.path)}</select><div class="mapping-preview"><canvas id="mapping-preview"></canvas></div><div class="mapping-controls">${['min','max','start','end','skew'].map(k=>`<d-knob data-path="mapping.${k}" label="${k.toUpperCase()}" value="${mappingDraft[k]}" default="${k==='max'||k==='end'?1:k==='skew'?.5:0}" format="percent"></d-knob>`).join('')}</div><label>CURVE</label><select id="mapping-curve">${[['linear','LINEAR'],['s','S-CURVE'],['triangle','TRIANGLE / THREE-POINT']].map(([v,l])=>`<option value="${v}"${(mappingDraft.curve||'linear')===v?' selected':''}>${l}</option>`).join('')}</select><p>MIN/MAX bestimmen die Zielwerte. START/END begrenzen den aktiven Bereich der Geste; SKEW formt ihren Verlauf. Umgekehrte Bereiche sind möglich.</p><div class="dialog-actions"><button data-close-dialog>CANCEL</button><button class="primary" id="mapping-save">${index<0?'ASSIGN TARGET':'APPLY ROUTING'}</button></div>`);
 d.addEventListener('close',()=>{const context=mappingContext;if(context&&!context.committed&&context.index>=0){context.source.targets[context.index]=context.original;host.send(state);writeStore('dd-session-v1',state);renderPage();}mappingContext=null;mappingDraft=null;},{once:true});$('#mapping-target').onchange=e=>{mappingDraft.path=e.target.value;previewMapping();};$('#mapping-curve').onchange=e=>{mappingDraft.curve=e.target.value;previewMapping();drawMapping();};$('#mapping-save').onclick=()=>{if(mappingContext)mappingContext.committed=true;if(index<0)src.targets.push(mappingDraft);else src.targets[index]=mappingDraft;d.close();mappingDraft=null;markDirty();send();renderPage();$$('d-knob').forEach(n=>n.badge());};requestAnimationFrame(drawMapping);}
function openAssignForTarget(path){if(!allTargets().some(t=>t.path===path))return;const assigned=sources().filter(s=>s.targets.some(t=>canonicalPath(t.path)===canonicalPath(path)));const d=showDialog('ASSIGN / '+esc(targetLabel(path)),`<p>Wähle die Quelle, die diesen Parameter steuern soll.</p><label>SOURCE</label><select id="assign-source">${sources().map(s=>`<option value="${s.key}"${s.targets.length>=s.max&&!s.targets.some(t=>t.path===path)?' disabled':''}>${s.label} · ${s.targets.length}/${s.max}</option>`).join('')}</select>${assigned.length?`<p class="accent">Zugewiesen: ${assigned.map(s=>s.label).join(', ')}</p>`:''}<div class="dialog-actions">${assigned.length?'<button id="unassign">REMOVE ASSIGNMENTS</button>':''}<button class="primary" id="assign-next">EDIT ROUTING ›</button></div>`);$('#assign-next').onclick=()=>{const key=$('#assign-source').value,s=sourceByKey(key),i=s.targets.findIndex(t=>canonicalPath(t.path)===canonicalPath(path));openMapping(key,i,path);};if($('#unassign'))$('#unassign').onclick=()=>{for(const s of assigned){const i=s.targets.findIndex(t=>canonicalPath(t.path)===canonicalPath(path));s.targets.splice(i,1);}d.close();markDirty();send();$$('d-knob').forEach(n=>n.badge());};}
function drawMapping(){const c=$('#mapping-preview');if(!c||!mappingDraft)return;plot(c,x=>mapTarget(x,mappingDraft),{grid:true});}
function engineDetails(key){const t=state.time[key],meta=key==='stutter'&&t.bend?'bend':key,d=showDialog(`${key.toUpperCase()} / SETTINGS`,`<p>Zusätzliche Optionen der Time-Engine.</p>${key==='stutter'?`<div class="knob-area" style="grid-template-columns:repeat(4,1fr)">${TIME_CONTROLS[meta].slice(6).map(([p,l,def,f])=>knob(`time.stutter.${p}`,l,def,f)).join('')}</div>`:''}${(TIME_SELECTS[meta]||[]).map(p=>`<div class="settings-row"><label>${p.label}</label>${select(`time.${key}.${p.key}`,p.options.map((v,i)=>[p.numeric?i/Math.max(1,p.options.length-1):v,v]))}</div>`).join('')}${(TIME_TOGGLES[meta]||[]).map(([k,l])=>`<div class="settings-row"><label>${l}</label>${toggle(`time.${key}.${k}`,getPath(state,`time.${key}.${k}`)?'ON':'OFF')}</div>`).join('')}<div class="dialog-actions"><button data-close-dialog>DONE</button></div>`);}
function openSave(){const d=showDialog('SAVE USER PRESET',`<p>Speichert Regler, Effektkette und Zuweisungen auf diesem Gerät.</p><label for="preset-name">NAME</label><input type="text" id="preset-name" maxlength="60" style="width:100%;margin:9px 0 16px" value="${esc(state.presetName==='Init'?'My preset':state.presetName)}"><div class="dialog-actions"><button data-close-dialog>CANCEL</button><button class="primary" id="save-user-preset">SAVE AS NEW PRESET</button></div>`);$('#save-user-preset').onclick=()=>{let name=$('#preset-name').value.trim();if(!name){$('#preset-name').focus();return;}const base=name;let n=2;while(FACTORIES.includes(name)||userPresets.some(p=>p.name===name))name=`${base} (${n++})`;const saved={name,state:structuredClone({...state,presetName:name,playing:false,bypass:false,automationPlaying:false})},next=[...userPresets,saved];if(!writeStore('dd-presets-v1',next)){download(new Blob([JSON.stringify(saved.state,null,2)],{type:'application/json'}),name.replace(/[^\w -]/g,'_')+'.json');d.close();toast('Browserspeicher voll · Preset als JSON-Datei exportiert.');return;}state.presetName=name;userPresets=next;writeStore('dd-session-v1',state);dirty=false;d.close();shell();toast('Preset gespeichert: '+name);};}
const randomSettings=readStore('dd-random-v1',{});
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
function exportPreset(){download(new Blob([JSON.stringify({...state,playing:false,bypass:false},null,2)],{type:'application/json'}),`${state.presetName.replace(/[^\w -]/g,'_')||'DA-Destructor'}.json`);toast('Preset exportiert.');}
function applyPreset(s){if(motion.active)stopMotion();const playing=host.playing;state=sanitizeState(s);settings.clock=state.clock.source;writeStore('dd-settings-v1',settings);state.playing=playing;dirty=false;host.processor?.port.postMessage({type:'reset'});host.send(state);writeStore('dd-session-v1',state);shell();}
async function action(name,button){switch(name){
 case 'motion-record':if(motion.active)stopMotion();else{await host.init(state);state.automationPlaying=false;send();motion.start(host.context.currentTime,motionInitialValues());toast('Bewegungsaufnahme läuft. Regler, Macros und XY bewegen.');renderPage();}break;
 case 'motion-play':if(!state.automation?.events?.length){toast('Zuerst eine Bewegung aufnehmen.');break;}if(motion.active)stopMotion();state.automationPlaying=!state.automationPlaying;motionReplayAcknowledged=false;motionReplayRequestedAt=performance.now();if(state.automationPlaying&&!host.playing)await host.play(state);host.send(state);renderPage();break;
 case 'motion-clear':motion.active=false;state.automation={duration:0,loop:true,events:[]};state.automationPlaying=false;markDirty();send();renderPage();break;
 case 'sidechain-file':$('#sidechain-file').click();break;
 case 'sidechain-connect':await host.connectSidechain($('#sidechain-device')?.value,state);renderPage();break;
 case 'sidechain-disconnect':host.disconnectSidechain();renderPage();break;

 case 'enable-midi':await host.init(state);await midi.enable();renderPage();toast(midi.inputs.length?`${midi.inputs.length} MIDI-Eingänge verfügbar.`:'Keine MIDI-Eingänge gefunden.');break;
 case 'clock-midi':state.clock.source='midi';settings.clock='midi';host.send(state);writeStore('dd-settings-v1',settings);renderPage();$('#bpm').disabled=true;toast(midi.selectedId?'MIDI Clock gewählt.':'MIDI freigeben und Eingang wählen.');break;
 case 'clock-internal':state.clock.source='internal';settings.clock='internal';host.send(state);writeStore('dd-settings-v1',settings);renderPage();$('#bpm').disabled=false;toast('Interne Clock gewählt.');break;
 case 'audio':if(!host.context){await host.play(state);if(page==='config')renderPage();}else if(host.playing)host.pause();else await host.play(state);break;
 case 'transport':if(host.playing)host.pause();else await host.play(state);break;
 case 'panic':if(motion.active)stopMotion();state.automationPlaying=false;host.stopRecording();host.reset();state.playing=false;state.time.vari.stop=false;state.time.vari.scratch=.5;host.send(state);updateTransport();toast('PANIC · Transport gestoppt, Speicher geleert.');break;
 case 'load-file':$('#audio-file').click();break;
 case 'demo':await host.demo(state);renderPage();toast('Factory loop geladen · 120 BPM / 4 Takte.');break;
 case 'restart':{const was=host.playing;host.reset();if(was)await host.play(state);break;}
 case 'live':await host.live($('#input-device')?.value,state);renderPage();await refreshDevices();break;
 case 'disconnect':host.pause();if(page==='source')renderPage();break;
 case 'refresh-devices':await refreshDevices();break;
 case 'record':if(host.recording)host.stopRecording();else {await host.record(state);toast('WAV-Aufnahme läuft · REC erneut drücken zum Speichern.');}break;
 case 'save-preset':openSave();break;
 case 'export-preset':exportPreset();break;
 case 'import-preset':$('#preset-file').click();break;
 case 'prev-preset':case 'next-preset':{const list=[...FACTORIES,...userPresets.map(p=>p.name)],i=Math.max(0,list.indexOf(state.presetName)),n=list[(i+(name==='next-preset'?1:list.length-1))%list.length];applyPreset(FACTORIES.includes(n)?factoryPreset(n):userPresets.find(p=>p.name===n).state);break;}
 case 'init':applyPreset(createState());toast('Init geladen.');break;
 case 'delete-preset':{const i=+$('#delete-preset')?.value;if(Number.isInteger(i)&&userPresets[i]){userPresets.splice(i,1);writeStore('dd-presets-v1',userPresets);shell();toast('Lokales User-Preset entfernt.');}break;}
 case 'random-time':['stretch','vari','stutter'].forEach(randomizeEngine);markDirty();send();renderPage();break;
 case 'random-fx':state.fx.forEach(randomizeFX);markDirty();send();renderPage();break;
 case 'random-setup':randomSetup();break;
 case 'clear-fx':{const ids=new Set(state.fx.map(f=>f.id));state.fx=[];removeTargets(t=>[...ids].some(id=>t.path.startsWith(`fx.${id}.`)));markDirty();send();renderPage();break;}
 case 'seq-random':for(const s of state.seq[seqEngine].steps.slice(seqPattern*16,seqPattern*16+16)){s.value=Math.random();s.on=Math.random()>.15;}captureSequence();markDirty();send();renderPage();break;
 case 'seq-fill':for(const s of state.seq[seqEngine].steps.slice(seqPattern*16,seqPattern*16+16)){s.value=seqEngine==='stretch'?1:.5;s.on=true;}captureSequence();markDirty();send();renderPage();break;
 case 'seq-toggle':for(const s of state.seq[seqEngine].steps.slice(seqPattern*16,seqPattern*16+16))s.on=!s.on;captureSequence();markDirty();send();renderPage();break;
 case 'seq-clear':for(const s of state.seq[seqEngine].steps.slice(seqPattern*16,seqPattern*16+16))s.on=false;captureSequence();markDirty();send();renderPage();break;
 case 'xy-center':changed('xy.x',.5);changed('xy.y',.5);updateXY();break;
 case 'engine-details':engineDetails(button.dataset.engineKey);break;
 case 'reset-accent':applyTheme(settings.theme,null);renderPage();break;
 case 'help':{const d=$('#help-dialog');d.innerHTML=`<div class="dialog-header"><h2>DA DESTRUCTOR / QUICK MANUAL</h2><button data-close-dialog aria-label="Schließen">×</button></div><div class="dialog-body"><p style="color:var(--muted);line-height:1.8;margin-bottom:19px">START AUDIO startet den Demo-Loop. Lade deine eigene Datei unter PLAY / LOAD oder ziehe sie ins Fenster. TIME verändert den Audiopuffer; das FX RACK verarbeitet den Ausgang. ANIMATE bewegt Parameter automatisch, PERFORM bündelt mehrere Parameter in einer Geste.</p>${helpRows()}<p style="color:var(--muted);line-height:1.8;margin-top:18px">Ein Klick auf einen Time-Regler aktiviert seine Engine beim Verändern. HOLD TO STOP hält das Band an; SCRATCH kehrt nach der Geste zur Mitte zurück. Effekte werden mit ↑/↓ oder Ziehen umsortiert. Leere und ausgeschaltete Prozesse werden umgangen.</p><p style="color:var(--muted);line-height:1.8;margin-top:14px">GRAPH: Klick setzt einen Punkt, Ziehen bewegt ihn, Shift-Ziehen formt das Segment. Rechtsklick entfernt Punkte. Im Sequencer schaltet ein Klick einen Step; Ziehen verändert seinen Wert. Bis zu vier Patterns laufen als Kette.</p><p style="color:var(--muted);line-height:1.8;margin-top:14px">Rechtsklick auf einen Regler weist Modulation zu. MIN/MAX begrenzen den Zielwert, START/END den Gestenbereich. MACRO und XY verwenden Pickup. Eine Aufnahme speichert den gesamten bearbeiteten Ausgang als Stereo-WAV. Themes und Presets liegen lokal im Browser.</p><div class="dialog-actions"><button class="primary" data-close-dialog>LET'S PLAY</button></div></div>`;d.showModal();break;}
}}
function removeTargets(predicate){for(const s of sources())for(let i=s.targets.length-1;i>=0;i--)if(predicate(s.targets[i]))s.targets.splice(i,1);}
function addEffect(type){if(state.fx.some(f=>f.type===type)){toast('Dieser Effekt ist bereits im Rack.');return;}const e=makeEffect(type);if(!e)return;state.fx.push(e);markDirty();send();renderPage();}
function reorderEffect(id,offset,target){const i=state.fx.findIndex(f=>f.id===id);if(i<0)return;const j=target?state.fx.findIndex(f=>f.id===target):Math.max(0,Math.min(state.fx.length-1,i+offset));if(j<0||i===j)return;state.fx.splice(j,0,state.fx.splice(i,1)[0]);markDirty();send();renderPage();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.hasAttribute('data-close-dialog')){b.closest('dialog').close();return;}
 if(b.dataset.page){setPage(b.dataset.page);if(page==='source')await refreshDevices();return;}
 if(b.dataset.action){await action(b.dataset.action,b);return;}
 if(b.dataset.toggle){const p=b.dataset.toggle;changed(p,!getPath(state,p));b.classList.toggle('active',!!getPath(state,p));b.setAttribute('aria-pressed',!!getPath(state,p));if(b.closest('dialog'))b.textContent=getPath(state,p)?'ON':'OFF';else renderPage();return;}
 if(b.dataset.valuePath){changed(b.dataset.valuePath,JSON.parse(b.dataset.value));renderPage();return;}
 if(b.dataset.local){if(b.dataset.local==='seq-engine')seqEngine=b.dataset.localValue;if(b.dataset.local==='seq-pattern')seqPattern=+b.dataset.localValue;renderPage();return;}
 if(b.dataset.graphSettings){const i=+b.dataset.graphSettings;showDialog(`GRAPH ${i+1} / CLOCK`,`<p>Musikalischer Modus: ¼ bis 16 Takte. Legacy erhält die früheren Preset-Zeiten.</p><div class="settings-row"><label>TIMING</label>${select(`graphs.${i}.timing`,[['musical','MUSICAL'],['legacy','LEGACY']])}</div><div class="dialog-actions"><button data-close-dialog>DONE</button></div>`);return;}
 if(b.dataset.graphHandles){const i=+b.dataset.graphHandles;if(graphHandles.has(i))graphHandles.delete(i);else graphHandles.add(i);renderPage();return;}
 if(b.dataset.fxChannel){fxChannels.set(b.dataset.fxChannel,b.dataset.channel);renderPage();return;}
 if(b.dataset.randomSetupFx){randomSetup('fx:'+b.dataset.randomSetupFx);return;}
 if(b.dataset.randomSetupEngine){randomSetup('time:'+b.dataset.randomSetupEngine);return;}
 if(b.dataset.addFx){addEffect(b.dataset.addFx);return;}
 if(b.dataset.removeFx){const id=b.dataset.removeFx;state.fx=state.fx.filter(f=>f.id!==id);removeTargets(t=>t.path.startsWith(`fx.${id}.`));markDirty();send();renderPage();return;}
 if(b.dataset.fxUp||b.dataset.fxDown){reorderEffect(b.dataset.fxUp||b.dataset.fxDown,b.dataset.fxUp?-1:1);return;}
 if(b.dataset.randomEngine){randomizeEngine(b.dataset.randomEngine);markDirty();send();renderPage();return;}
 if(b.dataset.randomFx){randomizeFX(state.fx.find(f=>f.id===b.dataset.randomFx));markDirty();send();renderPage();return;}
 if(b.dataset.addTarget){openMapping(b.dataset.addTarget);return;}
 if(b.dataset.editTarget){openMapping(b.dataset.editTarget,+b.dataset.targetIndex);return;}
 if(b.dataset.removeTarget){sourceByKey(b.dataset.removeTarget).targets.splice(+b.dataset.targetIndex,1);markDirty();send();renderPage();return;}
 if(b.dataset.resetGraph){state.graphs[+b.dataset.resetGraph].points=[[0,0],[.5,1],[1,0]];markDirty();send();drawPageCanvases();return;}
 if(b.dataset.themeName){applyTheme(b.dataset.themeName);renderPage();return;}
 }catch(error){toast(error.message||String(error),true);updateTransport();}});
document.addEventListener('input',e=>{const n=e.target;if(n.dataset.sliceSelector){sliceSelection.set(n.dataset.sliceSelector,+n.value);renderPage();}if(n.dataset.range){const v=+n.value;changed(n.dataset.range,v);const o=$(`[data-output="${n.dataset.range}"]`);if(o)o.textContent=Math.round(v*100)+' %';}if(n.id==='monitor-volume')host.setVolume(+n.value);if(n.id==='fx-search'){const q=n.value.trim().toUpperCase();$$('.effect-option').forEach(b=>b.hidden=!b.textContent.toUpperCase().includes(q));$$('.fx-category').forEach(d=>{d.hidden=!$$('.effect-option',d).some(b=>!b.hidden);if(q)d.open=true;});}if(n.id==='ui-scale'){settings.scale=+n.value;document.documentElement.style.zoom=n.value;$('#scale-value').textContent=Math.round(+n.value*100)+' %';writeStore('dd-settings-v1',settings);}if(n.id==='accent-color')applyTheme(settings.theme,n.value);if(n.dataset.randomStrength||n.dataset.randomProbability){const key=n.dataset.randomStrength||n.dataset.randomProbability,old=randomEntry(key);randomSettings[key]={...old,[n.dataset.randomStrength?'strength':'probability']:+n.value};n.nextElementSibling.textContent=Math.round(+n.value*100)+' %';writeStore('dd-random-v1',randomSettings);}});
document.addEventListener('change',e=>{const n=e.target;if(n.id==='midi-input'){midi.selectInput(n.value);const status=$('#midi-status');if(status)status.textContent=n.value?'WAITING FOR CLOCK':'NO MIDI INPUT SELECTED';}if(n.dataset.select){changed(n.dataset.select,JSON.parse(n.value));if(!n.closest('dialog'))renderPage();}if(n.id==='bpm'){state.bpm=clamp(n.value,30,300);n.value=state.bpm;markDirty();send();$$('d-knob').forEach(k=>k.setValue(k.value));}if(n.id==='preset-select'){const v=n.value;if(v.startsWith('f:'))applyPreset(factoryPreset(v.slice(2)));else if(v.startsWith('u:'))applyPreset(userPresets[+v.slice(2)].state);}if(n.dataset.macroName){state.macros[+n.dataset.macroName].name=n.value;markDirty();send();}});
$('#audio-file').addEventListener('change',async e=>{try{await loadAudio(e.target.files[0]);}catch(err){toast(err.message,true);}e.target.value='';});
$('#preset-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>16*1024*1024)throw new Error('Die Preset-Datei ist zu groß.');applyPreset(JSON.parse(await f.text()));toast('Preset importiert.');}catch(err){toast(err.message||'Preset konnte nicht geladen werden.',true);}e.target.value='';});
async function loadAudio(file){if(!file)return;toast('Audiodatei wird geladen…');await host.loadFile(file,state);toast(`Geladen: ${file.name} · ${host.buffer.duration.toFixed(2)} s`);if(page==='source')renderPage();}
async function refreshDevices(){const nodes=[$('#input-device'),$('#sidechain-device')].filter(Boolean);if(!nodes.length)return;const devices=await host.devices();for(const n of nodes){const selected=n.value;n.innerHTML='<option value="">System default</option>'+devices.map((d,i)=>`<option value="${esc(d.deviceId)}">${esc(d.label||`Audio input ${i+1}`)}</option>`).join('');if([...n.options].some(o=>o.value===selected))n.value=selected;}}
let gesture=null;
document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const hold=e.target.closest('[data-hold]');if(hold){e.preventDefault();hold.setPointerCapture(e.pointerId);changed(hold.dataset.hold,true);hold.classList.add('active');gesture={type:'hold',node:hold,path:hold.dataset.hold};return;}const step=e.target.closest('[data-step]');if(step){e.preventDefault();step.focus();step.setPointerCapture(e.pointerId);const i=+step.dataset.step;gesture={type:'step',node:step,index:i,y:e.clientY,value:state.seq[seqEngine].steps[i].value,moved:false};return;}const xy=e.target.closest('#xy-pad');if(xy){e.preventDefault();xy.focus();xy.setPointerCapture(e.pointerId);gesture={type:'xy',node:xy};moveXY(e);return;}const graph=e.target.closest('[data-graph]');if(graph){e.preventDefault();graph.focus();graph.setPointerCapture(e.pointerId);const i=+graph.dataset.graph,g=state.graphs[i],r=graph.getBoundingClientRect(),x=clamp((e.clientX-r.left)/r.width),y=clamp(1-(e.clientY-r.top)/r.height);let p=g.points.findIndex(p=>Math.abs(p[0]-x)*r.width<12&&Math.abs(p[1]-y)*r.height<15);if(p<0){if(g.points.length>=48)return;g.points.push([x,y,.5]);g.points.sort((a,b)=>a[0]-b[0]);p=g.points.findIndex(p=>p[0]===x&&p[1]===y);}gesture={type:'graph',node:graph,index:i,point:p,y:e.clientY,curve:g.points[p][2]??.5};markDirty();send();drawGraph(i);}});
document.addEventListener('pointermove',e=>{if(!gesture)return;const g=gesture;if(g.type==='step'){if(Math.abs(e.clientY-g.y)>3)g.moved=true;if(g.moved){const s=state.seq[seqEngine].steps[g.index];s.value=clamp(g.value+(g.y-e.clientY)/(e.shiftKey?1000:90));s.on=true;updateStep(g.node,s);markDirty();send();}}if(g.type==='xy')moveXY(e);if(g.type==='graph'){const points=state.graphs[g.index].points,p=points[g.point],r=g.node.getBoundingClientRect();if(e.shiftKey)p[2]=clamp(g.curve+(g.y-e.clientY)/100);else{p[1]=clamp(1-(e.clientY-r.top)/r.height);if(g.point>0&&g.point<points.length-1)p[0]=clamp((e.clientX-r.left)/r.width,points[g.point-1][0]+.005,points[g.point+1][0]-.005);}captureGraph(g.index,g.point);markDirty();send();drawGraph(g.index);}});
const finishGesture=e=>{if(!gesture)return;const g=gesture;gesture=null;if(g.type==='hold'){changed(g.path,false);g.node.classList.remove('active');}if(g.type==='step'&&!g.moved){const s=state.seq[seqEngine].steps[g.index];s.on=!s.on;updateStep(g.node,s);markDirty();send();}};document.addEventListener('pointerup',finishGesture);document.addEventListener('pointercancel',finishGesture);
window.addEventListener('blur',()=>{if(gesture?.type==='hold')finishGesture();if(state.time.vari.stop){state.time.vari.stop=false;send();}});
function updateStep(node,s){captureGesture(`seq.${seqEngine}.steps.${node.dataset.step}.value`,s.value);captureGesture(`seq.${seqEngine}.steps.${node.dataset.step}.on`,s.on);node.classList.toggle('disabled',!s.on);node.querySelector('.step-fill').style.height=s.value*65+2+'px';node.querySelector('.step-value').textContent=seqEngine==='stretch'?Math.round(s.value*100)+'%':state.time.stutter.bend?formatValue(s.value,'reps'):formatValue(s.value,'division');node.setAttribute('aria-valuenow',Math.round(s.value*100));}
function graphSegmentHandles(points,index){const a=points[index],b=points[index+1];if(!b)return null;if(a.length>=7&&a.slice(3,7).every(Number.isFinite))return a.slice(3,7);const bend=((a[2]??.5)-.5)*1.2;return [a[0]+(b[0]-a[0])/3,clamp(a[1]+(b[1]-a[1])/3+bend),a[0]+(b[0]-a[0])*2/3,clamp(a[1]+(b[1]-a[1])*2/3+bend)];}
document.addEventListener('pointerdown',e=>{const node=e.target.closest('[data-graph]');if(!node||e.button!==0||!graphHandles.has(+node.dataset.graph))return;const i=+node.dataset.graph,points=state.graphs[i].points,r=node.getBoundingClientRect();for(let j=0;j<points.length-1;j++){const handles=graphSegmentHandles(points,j);for(const h of [0,2])if(Math.hypot(e.clientX-r.left-handles[h]*r.width,e.clientY-r.top-(5+(1-handles[h+1])*(r.height-10)))<9){e.preventDefault();e.stopImmediatePropagation();node.setPointerCapture(e.pointerId);node.focus();points[j][2]??=.5;points[j].splice(3,4,...handles);gesture={type:'graph-handle',node,index:i,point:j,handle:h+3};return;}}},true);
document.addEventListener('pointermove',e=>{if(gesture?.type==='graph-handle'){const g=gesture,points=state.graphs[g.index].points,p=points[g.point],r=g.node.getBoundingClientRect();p[g.handle]=clamp((e.clientX-r.left)/r.width,p[0],points[g.point+1][0]);p[g.handle+1]=clamp(1-(e.clientY-r.top-5)/(r.height-10));captureGraph(g.index,g.point);markDirty();send();drawGraph(g.index);}else if(gesture?.type==='graph'){const g=gesture,points=state.graphs[g.index].points;if(g.point===0)points.at(-1)[1]=points[0][1];if(g.point===points.length-1)points[0][1]=points.at(-1)[1];if(e.shiftKey)points[g.point].length=3;captureGraph(g.index,g.point);markDirty();send();drawGraph(g.index);}});
document.addEventListener('contextmenu',e=>{const n=e.target.closest('[data-graph]');if(!n)return;e.preventDefault();const points=state.graphs[+n.dataset.graph].points,r=n.getBoundingClientRect(),x=(e.clientX-r.left)/r.width;let i=points.findIndex(p=>Math.abs(p[0]-x)*r.width<15);if(i>0&&i<points.length-1){points.splice(i,1);markDirty();send();drawGraph(+n.dataset.graph);}});
function moveXY(e){const r=gesture.node.getBoundingClientRect();changed('xy.x',clamp((e.clientX-r.left)/r.width));changed('xy.y',clamp(1-(e.clientY-r.top)/r.height));updateXY();}
function updateXY(){const n=$('#xy-pad');if(!n)return;$('.xy-dot',n).style.left=state.xy.x*100+'%';$('.xy-dot',n).style.top=(1-state.xy.y)*100+'%';$('.xy-line.v',n).style.left=state.xy.x*100+'%';$('.xy-line.h',n).style.top=(1-state.xy.y)*100+'%';$('#xy-x').textContent=`X ${state.xy.x.toFixed(2)}`;$('#xy-y').textContent=`Y ${state.xy.y.toFixed(2)}`;}
document.addEventListener('keydown',async e=>{if(e.target.closest('input,select,textarea')||document.querySelector('dialog[open]'))return;try{if(e.key==='Escape'){e.preventDefault();await action('panic');}if(e.code==='Space'&&!e.target.closest('button')){e.preventDefault();await action('transport');}if(e.target.closest('#xy-pad')&&e.key.startsWith('Arrow')){e.preventDefault();const d=e.shiftKey?.001:.01;if(e.key==='ArrowLeft')state.xy.x=clamp(state.xy.x-d);if(e.key==='ArrowRight')state.xy.x=clamp(state.xy.x+d);if(e.key==='ArrowUp')state.xy.y=clamp(state.xy.y+d);if(e.key==='ArrowDown')state.xy.y=clamp(state.xy.y-d);captureGesture('xy.x',state.xy.x);captureGesture('xy.y',state.xy.y);updateXY();markDirty();send();}const step=e.target.closest('[data-step]');if(step){const s=state.seq[seqEngine].steps[+step.dataset.step];if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();s.value=clamp(s.value+(e.key==='ArrowUp'?1:-1)*(e.shiftKey?.001:.02));s.on=true;updateStep(step,s);markDirty();send();}if(e.key==='Enter'){e.preventDefault();s.on=!s.on;updateStep(step,s);markDirty();send();}}}catch(err){toast(err.message,true);}});
let dragFx=null,dragDepth=0;
document.addEventListener('dragstart',e=>{const fx=e.target.closest('[data-drag-fx]'),lib=e.target.closest('[data-add-fx]');if(fx){dragFx={id:fx.dataset.dragFx};e.dataTransfer.setData('text/plain',fx.dataset.dragFx);e.dataTransfer.effectAllowed='move';}else if(lib){dragFx={type:lib.dataset.addFx};e.dataTransfer.setData('text/plain',lib.dataset.addFx);e.dataTransfer.effectAllowed='copy';}});
document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();dragDepth++;$('#drop-overlay').classList.add('show');}});
document.addEventListener('dragleave',e=>{if(e.dataTransfer.types.includes('Files')){dragDepth--;if(dragDepth<=0)$('#drop-overlay').classList.remove('show');}});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')||dragFx){e.preventDefault();if(dragFx){$$('.drag-over').forEach(n=>n.classList.remove('drag-over'));e.target.closest('[data-fx-id]')?.classList.add('drag-over');}}});
document.addEventListener('drop',async e=>{if(e.dataTransfer.files.length){e.preventDefault();dragDepth=0;$('#drop-overlay').classList.remove('show');try{await loadAudio(e.dataTransfer.files[0]);}catch(err){toast(err.message,true);}return;}if(dragFx){e.preventDefault();const target=e.target.closest('[data-fx-id]');if(dragFx.id&&target)reorderEffect(dragFx.id,0,target.dataset.fxId);if(dragFx.type&&e.target.closest('.fx-rack'))addEffect(dragFx.type);dragFx=null;$$('.drag-over').forEach(n=>n.classList.remove('drag-over'));}});
document.addEventListener('dragend',()=>{dragFx=null;$$('.drag-over').forEach(n=>n.classList.remove('drag-over'));});

host.addEventListener('error',e=>toast(e.detail,true));
midi.addEventListener('error',e=>toast(e.detail,true));
midi.addEventListener('inputs',()=>{if(page==='config')renderPage();});
midi.addEventListener('clock',async e=>{if(settings.clock!=='midi')return;const c=e.detail;try{state.clock.source='midi';if(c.bpm&&Math.abs(state.bpm-c.bpm)>.05){state.bpm=clamp(c.bpm,30,300);const b=$('#bpm');if(b)b.value=state.bpm.toFixed(1);send();}const n=$('#midi-status');if(n)n.textContent=c.kind==='disconnect'?'INPUT DISCONNECTED':`${c.playing?'RUNNING':'STOPPED'} / ${c.bpm?.toFixed(1)||'—'} BPM`;if(c.kind==='start'){host.reset();await host.play(state);host.clock(c.beat,c.bpm,c.playing,c.timestamp);}else if(c.kind==='continue'){await host.play(state);host.clock(c.beat,c.bpm,c.playing,c.timestamp);}else if(c.kind==='pulse'||c.kind==='position')host.clock(c.beat,c.bpm,c.playing,c.timestamp,{seek:c.kind==='position'});else if(['stop','disconnect','input'].includes(c.kind))host.pause();}catch(err){toast(err.message,true);}});
host.addEventListener('ready',()=>{toast('Audio-Engine bereit.');updateTransport();});
host.addEventListener('source',e=>{sourceInfo=e.detail;waveData=null;$('#source-name').textContent=host.sourceName;$('#source-description').textContent=sourceDescription();$('#source-label').textContent=host.sourceKind==='live'?'LIVE INPUT':'LOOP SOURCE';drawWaveform();});
host.addEventListener('transport',()=>updateTransport());
host.addEventListener('meter',e=>{meters=e.detail;reflectMeters(meters);for(const [id,v]of [['meter-l',meters.peakL],['meter-r',meters.peakR]]){const n=$('#'+id);if(n)n.style.height=clamp((20*Math.log10(Math.max(.0001,v))+60)/60)*100+'%';}const peak=Math.max(meters.peakL||0,meters.peakR||0),n=$('#peak-readout');if(n){n.textContent=peak>1e-4?`${(20*Math.log10(peak)).toFixed(1)} dB`:'−∞ dB';n.classList.toggle('clip',peak>.98);}$$('.beat-dots i').forEach((n,i)=>n.classList.toggle('active',host.playing&&Math.floor(meters.beat||0)%4===i));for(let i=0;i<4;i++){const n=$('#mod-val-'+i);if(n)n.textContent=(meters.mods?.[i]||0).toFixed(2);}if(page==='time'){const q=state.seq[seqEngine],step=Math.floor((meters.beat||0)/[.25,.5,1,2,4][Math.round(q.rate*4)])%(q.patterns*16);$$('[data-step]').forEach(n=>n.classList.toggle('current',q.on&&host.playing&&+n.dataset.step===step));const p=$('#seq-position');if(p)p.textContent=`${String.fromCharCode(65+Math.floor(step/16))} / ${String(step%16+1).padStart(2,'0')}`;}});
host.addEventListener('record',e=>{$$('[data-action="record"]').forEach(b=>{b.classList.toggle('active',e.detail);b.textContent=e.detail?'● STOP & SAVE':'● REC WAV';});});
host.addEventListener('recorded',e=>{download(e.detail.blob,`DA-Destructor-${new Date().toISOString().replace(/[:.]/g,'-')}.wav`);toast(`WAV gespeichert · ${e.detail.duration.toFixed(2)} s`);});
function updateTransport(){const b=$('[data-action="audio"]');if(b){b.textContent=!host.context?'●  START AUDIO':host.playing?'●  AUDIO RUNNING':'▶  START AUDIO';b.classList.toggle('primary',!host.context||host.playing);}$$('[data-action="transport"]').forEach(n=>{n.textContent=host.playing?'Ⅱ':'▶';n.title=host.playing?'Wiedergabe pausieren':'Wiedergabe starten';});const hint=$('#hint');if(hint)hint.textContent=host.playing?'Audio läuft · '+host.sourceName:'Bereit · START AUDIO oder Audiodatei hineinziehen.';}

function canvasContext(canvas){const r=canvas.getBoundingClientRect(),d=Math.min(2,devicePixelRatio||1);if(!r.width||!r.height)return;const w=Math.round(r.width*d),h=Math.round(r.height*d);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}const ctx=canvas.getContext('2d');ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,r.width,r.height);return {ctx,w:r.width,h:r.height,accent:getComputedStyle(document.documentElement).getPropertyValue('--accent').trim(),line:getComputedStyle(document.documentElement).getPropertyValue('--line').trim()};}
function plot(canvas,fn,{grid=false,phase=null}={}){const info=canvasContext(canvas);if(!info)return;const {ctx,w,h,accent,line}=info;if(grid){ctx.strokeStyle=line;ctx.lineWidth=1;ctx.beginPath();for(let i=1;i<4;i++){ctx.moveTo(w*i/4,0);ctx.lineTo(w*i/4,h);ctx.moveTo(0,h*i/4);ctx.lineTo(w,h*i/4);}ctx.stroke();}ctx.strokeStyle=accent;ctx.lineWidth=1.3;ctx.beginPath();for(let x=0;x<=w;x++){const y=clamp(fn(x/w));if(x===0)ctx.moveTo(x,5+(1-y)*(h-10));else ctx.lineTo(x,5+(1-y)*(h-10));}ctx.stroke();if(phase!=null){ctx.globalAlpha=.5;ctx.beginPath();ctx.moveTo(phase*w,0);ctx.lineTo(phase*w,h);ctx.stroke();ctx.globalAlpha=1;}}
function drawWaveform(){const c=$('#waveform');if(!c)return;const info=canvasContext(c);if(!info)return;const {ctx,w,h,accent}=info;ctx.strokeStyle=accent;ctx.globalAlpha=.5;ctx.lineWidth=1;ctx.beginPath();if(host.sourceKind==='live'){const live=host.getInputWave();if(live){for(let x=0;x<w;x++){const y=h*.5-live[Math.floor(x/w*live.length)]*h*.4;x?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();ctx.globalAlpha=1;return;}}const data=host.buffer?.getChannelData(0);if(data&&!waveData){const count=1000;waveData=Array.from({length:count},(_,j)=>{let max=0;const a=Math.floor(j*data.length/count),b=Math.floor((j+1)*data.length/count),stride=Math.max(1,Math.floor((b-a)/60));for(let i=a;i<b;i+=stride)max=Math.max(max,Math.abs(data[i]));return max;});}for(let x=0;x<w;x+=2){const v=waveData?waveData[Math.min(waveData.length-1,Math.floor(x/w*waveData.length))]:.08+.55*Math.exp(-((x/w*32)%1)*5)+.08*Math.sin(x*2.2);ctx.moveTo(x,h*.5-v*h*.37);ctx.lineTo(x,h*.5+v*h*.37);}ctx.stroke();ctx.globalAlpha=1;}
function drawGraph(i){const el=$(`[data-graph="${i}"]`);if(!el)return;const g=state.graphs[i],points=prepareGraph(g.points),period=(g.timing==='legacy'?[.0625,.125,.25,.5,1,2,4,8,16,32,64]:[1,2,4,6,8,12,16,24,32,48,64])[Math.round(g.rate*10)],phase=host.playing?(meters.graphPhases?.[i]??((meters.beat||0)/period)%1):null;plot($('canvas',el),x=>graphValue(points,x),{grid:true,phase});const {ctx,w,h,accent}=canvasContextNoClear($('canvas',el));if(graphHandles.has(i)){ctx.strokeStyle=accent;ctx.fillStyle=accent;ctx.lineWidth=.8;for(let j=0;j<g.points.length-1;j++){const a=g.points[j],b=g.points[j+1],handles=graphSegmentHandles(g.points,j);ctx.globalAlpha=.5;ctx.beginPath();ctx.moveTo(a[0]*w,5+(1-a[1])*(h-10));ctx.lineTo(handles[0]*w,5+(1-handles[1])*(h-10));ctx.moveTo(b[0]*w,5+(1-b[1])*(h-10));ctx.lineTo(handles[2]*w,5+(1-handles[3])*(h-10));ctx.stroke();ctx.globalAlpha=1;for(const at of [0,2])ctx.fillRect(handles[at]*w-2.5,5+(1-handles[at+1])*(h-10)-2.5,5,5);}}ctx.fillStyle=accent;for(const p of g.points){ctx.beginPath();ctx.arc(p[0]*w,5+(1-p[1])*(h-10),3,0,Math.PI*2);ctx.fill();}}

function canvasContextNoClear(canvas){const r=canvas.getBoundingClientRect();return {ctx:canvas.getContext('2d'),w:r.width,h:r.height,accent:getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()};}
function drawPageCanvases(){if(page==='time')$$('[data-engine-scope]').forEach(c=>{const key=c.dataset.engineScope,t=state.time[key],phase=host.playing?(meters.beat||0)*.1:0;plot(c,x=>key==='stretch'?.5+.23*Math.sin(x*Math.PI*14+phase*10)*Math.sin(x*Math.PI*2):key==='vari'?.5+.22*Math.sin(x*35*(.3+t.speed*.7)+Math.sin(x*9)*t.wow):t.bend?.5+.25*Math.sin(Math.floor(x*(4+t.reps*28))*2.3+phase*10)*(1-t.break*.7):.12+.7*Math.exp(-((x*6+phase)%1)*(2+t.gate*10)),{grid:false});});if(page==='animate'){for(let i=0;i<4;i++){const c=$(`[data-mod-scope="${i}"]`),m=state.mods[i];if(c)plot(c,x=>m.type==='lfo'?lfoShape(m.shape,x):m.type==='rand'?(.5+.3*Math.sin(Math.floor(x*9)*29.23)):clamp((meters.mods?.[i]||.02)*Math.exp(-x*2)),{grid:true,phase:host.playing?(meters.modPhases?.[i]??((meters.beat||0)/[.0625,.125,.25,.5,1,2,4,8,16,32,64][Math.round(m.rate*10)])%1):null});}for(let i=0;i<3;i++)drawGraph(i);}}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${(s%60).toFixed(2).padStart(5,'0')}`;}
let lastDraw=0;
function animate(now){if(now-lastDraw>65){lastDraw=now;if(host.playing){if(host.sourceKind==='live')drawWaveform();const pos=host.currentPosition;const n=$('#time-display');if(n)n.textContent=formatTime(pos);const ph=$('#playhead');if(ph)ph.style.left=(host.sourceKind==='live'?((meters.beat||0)%16)/16:pos/(host.buffer?.duration||8))*100+'%';drawPageCanvases();}if(motion.active){const d=$('#motion-time');if(d)d.textContent=formatTime((host.context?.currentTime??0)-motion.started);if((host.context?.currentTime??0)-motion.started>=600)stopMotion();}if(host.recording){const elapsed=(now-host.recordStarted)/1000;const n=$('#record-time');if(n)n.textContent=formatTime(elapsed);if(elapsed>600){host.stopRecording();toast('10 Minuten aufgenommen · WAV wird gespeichert.');}}}requestAnimationFrame(animate);}
window.addEventListener('resize',()=>{drawWaveform();drawPageCanvases();});
window.addEventListener('beforeunload',()=>{if(host.playing)host.pause();writeStore('dd-session-v1',state);});
document.addEventListener('visibilitychange',()=>{if(document.hidden)writeStore('dd-session-v1',state);});
document.body.insertAdjacentHTML('beforeend','<input type="file" id="sidechain-file" accept="audio/*,.wav,.flac,.mp3,.ogg,.m4a" hidden>');$('#sidechain-file').addEventListener('change',async e=>{try{if(e.target.files[0]){await host.loadSidechain(e.target.files[0],state);toast('Sidechain geladen.');if(page==='source')renderPage();}}catch(error){toast(error.message,true);}e.target.value='';});host.addEventListener('sidechain',()=>{const n=$('#sidechain-name');if(n)n.textContent=host.sidechain.name;});shell();requestAnimationFrame(animate);
